const EXERCISES = [{"id":"ex-ent-01","topic":"Entropy","level":1,"q":"Tập dữ liệu D có 6 mẫu Good và 4 mẫu Bad. Hãy tính Entropy(D) theo đơn vị bit.","given":["|D| = 10","Good = 6","Bad = 4"],"opts":["0,971","1,000","0,673","0,292"],"ans":[0],"sol":["p(Good) = 6/10 = 0,600 ; p(Bad) = 4/10 = 0,400","log₂0,600 ≈ −0,737 ; log₂0,400 ≈ −1,322","Entropy(D) = −(0,600·(−0,737) + 0,400·(−1,322)) = 0,442 + 0,529","Kết quả: 0,971 bit"],"kq":"0,971 bit","note":"Bắt buộc dùng log₂. Ra 0,292 là đã dùng log₁₀, ra 0,673 là đã dùng ln."},{"id":"ex-ent-02","topic":"Entropy","level":1,"q":"Một tập huấn luyện có 7 mẫu Good và 3 mẫu Bad. Tính Entropy của tập này (bit).","given":["|D| = 10","Good = 7","Bad = 3"],"opts":["1,000","0,881","0,611","0,265"],"ans":[1],"sol":["p(Good) = 7/10 = 0,700 ; p(Bad) = 3/10 = 0,300","log₂0,700 ≈ −0,515 ; log₂0,300 ≈ −1,737","Entropy(D) = 0,360 + 0,521","Kết quả: 0,881 bit"],"kq":"0,881 bit","note":"Tập càng lệch về một lớp thì entropy càng nhỏ: 0,881 < 0,971 của trường hợp 6/4."},{"id":"ex-ent-06","topic":"Entropy","level":1,"q":"Một nút trong cây quyết định có 5 mẫu Good và 1 mẫu Bad. Tính Entropy của nút này.","given":["|D| = 6","Good = 5","Bad = 1"],"opts":["0,196","0,833","0,451","0,650"],"ans":[3],"sol":["p(Good) = 5/6 ≈ 0,833 ; p(Bad) = 1/6 ≈ 0,167","log₂0,833 ≈ -0,263 ; log₂0,167 ≈ -2,585","Entropy = 0,219 + 0,431","Kết quả: 0,650 bit"],"kq":"0,650 bit","note":"0,196 là lỗi dùng log₁₀; 0,833 là lỗi trả p(Good) thay vì entropy."},{"id":"ex-ent-03","topic":"Entropy","level":2,"q":"Tập D gồm 10 mẫu được chia thành 3 lớp: 5 mẫu Good, 3 mẫu Fair và 2 mẫu Bad. Tính Entropy(D).","given":["|D| = 10","Good = 5 ; Fair = 3 ; Bad = 2"],"opts":["0,447","1,585","1,485","1,030"],"ans":[2],"sol":["p(Good) = 0,500 ; p(Fair) = 0,300 ; p(Bad) = 0,200","log₂0,500 = −1,000 ; log₂0,300 ≈ −1,737 ; log₂0,200 ≈ −2,322","Entropy(D) = 0,500 + 0,521 + 0,464","Kết quả: 1,485 bit"],"kq":"1,485 bit","note":"Với 3 lớp, entropy cực đại là log₂3 = 1,585 chứ không phải 1; đáp án 1,585 là lỗi lấy luôn cực đại."},{"id":"ex-ent-07","topic":"Entropy","level":2,"q":"Tập D có 10 mẫu: 6 Good, 3 Fair, 1 Bad. Tính Entropy(D) theo bit.","given":["|D| = 10","Good = 6 ; Fair = 3 ; Bad = 1"],"opts":["0,390","1,585","1,295","0,898"],"ans":[2],"sol":["p = 0,600 ; 0,300 ; 0,100","log₂0,600 ≈ -0,737 ; log₂0,300 ≈ -1,737 ; log₂0,100 ≈ -3,322","Entropy = 0,442 + 0,521 + 0,332","Kết quả: 1,295 bit"],"kq":"1,295 bit","note":"Entropy tương đối so với cực đại log₂3 = 1,585 là 81,7%, nhưng đề chỉ hỏi entropy tuyệt đối."},{"id":"ex-ent-09","topic":"Entropy","level":2,"q":"Một nút có 9 Good và 1 Bad. Ba nút phụ khác có 8 Good, 2 Bad; 7 Good, 3 Bad và 6 Good, 4 Bad. Tính Entropy của nút thứ nhất và cho biết nó có thuần khiết nhất trong bốn nút không.","given":["Nút chính : 9 Good, 1 Bad","Nút A : 8 Good, 2 Bad","Nút C : 7 Good, 3 Bad","Nút D : 6 Good, 4 Bad"],"opts":["0,469","0,722","0,881","0,971"],"ans":[0],"sol":["Nút chính: p(Good) = 9/10 = 0,900 ; p(Bad) = 1/10 = 0,100","log₂0,900 ≈ -0,152 ; log₂0,100 ≈ -3,322","Entropy = 0,137 + 0,332","So sánh: 0,469 < 0,722 < 0,881 < 0,971 nên đây là nút thuần khiết nhất","Kết quả: 0,469 bit"],"kq":"0,469 bit","note":"Entropy nhỏ nhất khi tỉ lệ lớp lệch nhất. Các phương án còn lại là entropy của ba nút phụ — bẫy chọn nhầm nút."},{"id":"ex-ent-04","topic":"Entropy","level":3,"q":"Hai tập dữ liệu D₁ và D₂ có phân bố nhãn như bảng dưới (mỗi tập 10 mẫu). Hỏi Entropy(D₁) lớn hơn Entropy(D₂) bao nhiêu bit?","given":["D₁ : Bad = 4, Good = 6 (|D₁| = 10)","D₂ : Bad = 2, Good = 8 (|D₂| = 10)"],"opts":["0,971","1,693","0,722","0,249"],"ans":[3],"sol":["Entropy(D₁) = −(0,600·log₂0,600 + 0,400·log₂0,400) = 0,971","Entropy(D₂) = −(0,800·log₂0,800 + 0,200·log₂0,200) = 0,722","Chênh lệch = 0,971 − 0,722 = 0,249","Kết quả: 0,249 bit"],"kq":"0,249 bit","note":"Đề hỏi hiệu hai entropy. Đáp án 1,693 là lỗi cộng hai entropy thay vì trừ."},{"id":"ex-ent-08","topic":"Entropy","level":3,"q":"Hai tập có cùng 10 mẫu nhưng phân bố 3 lớp khác nhau (bảng dưới). Entropy của tập phân bố đều hơn lớn hơn entropy của tập kia bao nhiêu bit?","given":["D₁ : 6 Good, 2 Fair, 2 Bad","D₂ : 4 Good, 4 Fair, 2 Bad"],"opts":["1,522","0,151","2,893","1,371"],"ans":[1],"sol":["Entropy(D₁) = −(0,6·log₂0,6 + 0,2·log₂0,2 + 0,2·log₂0,2) = 1,371","Entropy(D₂) = −(0,4·log₂0,4 + 0,4·log₂0,4 + 0,2·log₂0,2) = 1,522","D₂ đều hơn nên Entropy(D₂) lớn hơn: 1,522 − 1,371 = 0,151","Kết quả: 0,151 bit"],"kq":"0,151 bit","note":"Phân bố càng đều giữa các lớp thì entropy càng gần log₂3 = 1,585. 2,893 là lỗi cộng hai entropy."},{"id":"ex-ent-05","topic":"Entropy","level":4,"q":"Tập D có 12 mẫu Good, 5 mẫu Fair và 3 mẫu Bad (|D| = 20). Biết entropy cực đại của bài toán 3 lớp là log₂3 = 1,585. Entropy tương đối của D (tính theo % so với cực đại) bằng bao nhiêu?","given":["|D| = 20","Good = 12 ; Fair = 5 ; Bad = 3","log₂3 = 1,585"],"opts":["85,347%","100,0%","135,272%","31,299%"],"ans":[0],"sol":["p = 0,600 ; 0,250 ; 0,150","Entropy(D) = 1,353 bit","Entropy tương đối = 1,353 / 1,585 = 0,853","Kết quả: 85,347%"],"kq":"85,347%","note":"Mẫu số là log₂(số lớp) = log₂3, không phải log₂|D|. Chia cho log₂20 ra 31,3% là bẫy."},{"id":"ex-ig-06","topic":"Information Gain","level":1,"q":"Tập D có 14 mẫu (9 Good, 5 Bad). Đây là bước đầu tiên khi tính Information Gain. Hãy tính Info(D).","given":["|D| = 14 : Good = 9, Bad = 5"],"opts":["0,283","0,961","0,971","0,940"],"ans":[3],"sol":["p(Good) = 9/14 ≈ 0,643 ; p(Bad) = 5/14 ≈ 0,357","log₂0,643 ≈ -0,637 ; log₂0,357 ≈ -1,485","Info(D) = 0,643·0,637 + 0,357·1,485 = 0,410 + 0,531","Kết quả: 0,940 bit"],"kq":"0,940 bit","note":"0,283 là lỗi dùng log₁₀. Các phương án khác là lỗi đọc nhầm số mẫu (9/6, 8/5)."},{"id":"ex-ig-01","topic":"Information Gain","level":2,"q":"Tập D có 14 mẫu (9 Good, 5 Bad). Thuộc tính A chia D thành 3 nhánh như bảng. Tính Information Gain của thuộc tính A.","given":["|D| = 14 : 9 Good, 5 Bad","A₁ : 5 mẫu (2 Good, 3 Bad)","A₂ : 4 mẫu (4 Good, 0 Bad)","A₃ : 5 mẫu (3 Good, 2 Bad)"],"opts":["0,940","0,247","0,694","0,293"],"ans":[1],"sol":["Info(D) = −(9/14)·log₂(9/14) − (5/14)·log₂(5/14) = 0,940","Info(A₁) = H(2,3) = 0,971 ; Info(A₂) = H(4,0) = 0,000 ; Info(A₃) = H(3,2) = 0,971","Info_A(D) = (5/14)·0,971 + (4/14)·0 + (5/14)·0,971 = 0,347 + 0 + 0,347 = 0,694","Gain(A) = 0,940 − 0,694 = 0,247","Kết quả: 0,247 bit"],"kq":"0,247 bit","note":"Nhánh thuần (4 Good, 0 Bad) có entropy bằng 0. Quên trọng số |Dj|/|D| sẽ ra 0,293."},{"id":"ex-ig-02","topic":"Information Gain","level":2,"q":"Tập D có 10 mẫu (6 Good, 4 Bad) được chia theo thuộc tính A thành 2 nhánh bằng nhau. Tính Gain(A).","given":["|D| = 10 : 6 Good, 4 Bad","A₁ : 5 mẫu (4 Good, 1 Bad)","A₂ : 5 mẫu (2 Good, 3 Bad)"],"opts":["0,361","0,846","0,125","0,971"],"ans":[2],"sol":["Info(D) = 0,971","Info(A₁) = H(4,1) = 0,722 ; Info(A₂) = H(2,3) = 0,971","Info_A(D) = 0,5·0,722 + 0,5·0,971 = 0,361 + 0,485 = 0,846","Gain(A) = 0,971 − 0,846 = 0,125","Kết quả: 0,125 bit"],"kq":"0,125 bit","note":"Hai nhánh bằng nhau nên trọng số đều là 0,5. Đáp án 0,846 là lỗi trả Info_A thay vì Gain."},{"id":"ex-ig-03","topic":"Information Gain","level":2,"q":"Trên cùng tập D (10 mẫu: 6 Good, 4 Bad) dùng để tính Information Gain, thuộc tính B chia D thành 2 nhánh như bảng. Tính Info_B(D) — phần thông tin còn lại sau khi chia theo B.","given":["|D| = 10 : 6 Good, 4 Bad","B₁ : 6 mẫu (5 Good, 1 Bad)","B₂ : 4 mẫu (1 Good, 3 Bad)"],"opts":["0,811","0,650","0,390","0,715"],"ans":[3],"sol":["Trọng số: |B₁|/|D| = 6/10 = 0,600 ; |B₂|/|D| = 4/10 = 0,400","Info(B₁) = H(5,1) = 0,650 ; Info(B₂) = H(1,3) = 0,811","Info_B(D) = 0,600·0,650 + 0,400·0,811 = 0,390 + 0,325","Kết quả: 0,715 bit"],"kq":"0,715 bit","note":"Đề hỏi Info_B(D) chứ không phải Gain: Gain(B) = 0,971 − 0,715 = 0,256."},{"id":"ex-ig-07","topic":"Information Gain","level":2,"q":"Tập D có 14 mẫu (9 Good, 5 Bad) được chia theo thuộc tính A thành 2 nhánh bằng nhau. Tính Gain(A).","given":["|D| = 14 : 9 Good, 5 Bad","A₁ : 7 mẫu (6 Good, 1 Bad)","A₂ : 7 mẫu (3 Good, 4 Bad)"],"opts":["0,788","0,592","0,152","0,985"],"ans":[2],"sol":["Info(D) = 0,940","Info(A₁) = H(6,1) = 0,592 ; Info(A₂) = H(3,4) = 0,985","Info_A(D) = 0,5·0,592 + 0,5·0,985 = 0,788","Gain(A) = 0,940 − 0,788 = 0,152","Kết quả: 0,152 bit"],"kq":"0,152 bit","note":"0,788 là lỗi trả Info_A thay vì Gain. Hai nút con ở đây đều khá lệch lớp nên Gain vẫn dương nhưng nhỏ."},{"id":"ex-ig-09","topic":"Information Gain","level":2,"q":"Tập D có 16 mẫu (10 Good, 6 Bad). Thuộc tính X chia D thành 3 nhánh. Tính Gain(X) theo bit.","given":["|D| = 16 : 10 Good, 6 Bad","X₁ : 6 mẫu (5 Good, 1 Bad)","X₂ : 5 mẫu (3 Good, 2 Bad)","X₃ : 5 mẫu (2 Good, 3 Bad)"],"opts":["0,104","0,851","0,971","0,954"],"ans":[0],"sol":["Info(D) = −(10/16)·log₂(10/16) − (6/16)·log₂(6/16) = 0,954","Info(X₁) = 0,650 ; Info(X₂) = 0,971 ; Info(X₃) = 0,971","Info_X(D) = (6/16)·0,650 + (5/16)·0,971 + (5/16)·0,971 = 0,851","Gain(X) = 0,954 − 0,851 = 0,104","Kết quả: 0,104 bit"],"kq":"0,104 bit","note":"X₂ và X₃ đối xứng nhau (3/2 so với 2/3) nên cùng entropy 0,971, nhưng trọng số khác nhau: 5/16 mỗi bên."},{"id":"ex-ig-04","topic":"Information Gain","level":3,"q":"Tập D có 14 mẫu (9 Good, 5 Bad). Thuộc tính X chia D thành 3 nhánh như bảng. Tính Gain(X).","given":["|D| = 14 : 9 Good, 5 Bad","X₁ : 6 mẫu (5 Good, 1 Bad)","X₂ : 5 mẫu (3 Good, 2 Bad)","X₃ : 3 mẫu (1 Good, 2 Bad)"],"opts":["0,118","0,822","0,279","0,940"],"ans":[0],"sol":["Info(D) = 0,940","Info(X₁) = 0,650 ; Info(X₂) = 0,971 ; Info(X₃) = 0,918","Info_X(D) = (6/14)·0,650 + (5/14)·0,971 + (3/14)·0,918 = 0,279 + 0,347 + 0,197 = 0,822","Gain(X) = 0,940 − 0,822 = 0,118","Kết quả: 0,118 bit"],"kq":"0,118 bit","note":"Ba nhánh có kích thước khác nhau nên trọng số khác nhau: 6/14, 5/14, 3/14."},{"id":"ex-ig-08","topic":"Information Gain","level":3,"q":"Tập D có 14 mẫu (9 Good, 5 Bad). Thuộc tính B chia thành 3 nhánh với kích thước khác nhau. Tính Gain(B).","given":["|D| = 14 : 9 Good, 5 Bad","B₁ : 8 mẫu (6 Good, 2 Bad)","B₂ : 4 mẫu (2 Good, 2 Bad)","B₃ : 2 mẫu (1 Good, 1 Bad)"],"opts":["0,892","0,048","0,477","0,811"],"ans":[1],"sol":["Info(D) = 0,940","Info(B₁) = 0,811 ; Info(B₂) = 1,000 ; Info(B₃) = 1,000","Info_B(D) = (8/14)·0,811 + (4/14)·1,000 + (2/14)·1,000 = 0,464 + 0,286 + 0,143 = 0,892","Gain(B) = 0,940 − 0,892 = 0,048","Kết quả: 0,048 bit"],"kq":"0,048 bit","note":"Hai nhánh B₂ và B₃ chia đôi hoàn toàn (2 Good/2 Bad và 1 Good/1 Bad) nên đều có entropy bằng 1,000 — độ hỗn loạn cao nhất. Gain vì thế rất nhỏ."},{"id":"ex-ig-05","topic":"Information Gain","level":4,"q":"Tập D có 16 mẫu (10 Good, 6 Bad). Hai thuộc tính A và B chia D như bảng. Thuộc tính nào được chọn theo Information Gain, và Gain của thuộc tính đó bằng bao nhiêu?","given":["|D| = 16 : 10 Good, 6 Bad","A₁ : 9 mẫu (8 Good, 1 Bad) ; A₂ : 7 mẫu (2 Good, 5 Bad)","B₁ : 6 mẫu (5 Good, 1 Bad) ; B₂ : 6 mẫu (4 Good, 2 Bad) ; B₃ : 4 mẫu (1 Good, 3 Bad)"],"opts":["0,954","0,294","0,163","0,661"],"ans":[1],"sol":["Info(D) = 0,954","Info_A(D) = (9/16)·0,503 + (7/16)·0,863 = 0,661 ⇒ Gain(A) = 0,294","Info_B(D) = (6/16)·0,650 + (6/16)·0,918 + (4/16)·0,811 = 0,791 ⇒ Gain(B) = 0,163","Gain(A) = 0,294 > Gain(B) = 0,163 nên chọn A","Kết quả: 0,294 bit"],"kq":"0,294 bit","note":"Chia nhiều nhánh hơn chưa chắc tốt hơn: B có 3 nhánh nhưng Gain thấp hơn A."},{"id":"ex-ig-10","topic":"Information Gain","level":4,"q":"Tập D có 20 mẫu (12 Good, 8 Bad). Hai thuộc tính Age và Gender chia D như bảng. Gain(Age) lớn hơn Gain(Gender) bao nhiêu bit?","given":["|D| = 20 : 12 Good, 8 Bad","Age₁ : 8 mẫu (7 Good, 1 Bad) ; Age₂ : 7 mẫu (4 Good, 3 Bad) ; Age₃ : 5 mẫu (1 Good, 4 Bad)","Gender₁ : 11 mẫu (8 Good, 3 Bad) ; Gender₂ : 9 mẫu (4 Good, 5 Bad)"],"opts":["0,060","0,228","0,743","0,168"],"ans":[3],"sol":["Info(D) = −(12/20)·log₂0,6 − (8/20)·log₂0,4 = 0,971","Info_Age(D) = 0,4·0,544 + 0,35·0,985 + 0,25·0,722 = 0,743 ⇒ Gain(Age) = 0,228","Info_Gender(D) = 0,55·0,845 + 0,45·0,991 = 0,911 ⇒ Gain(Gender) = 0,060","Chênh lệch = 0,228 − 0,060 = 0,168","Kết quả: 0,168 bit"],"kq":"0,168 bit","note":"Gender gần như vô dụng (Gain chỉ 0,060) vì hai nhánh có tỉ lệ lớp xấp xỉ nhau. Đáp án 0,228 là lỗi trả Gain(Age)."},{"id":"ex-mm-01","topic":"Min-Max","level":1,"q":"Cột Thu nhập có min = 10 (triệu đồng), max = 110 (triệu đồng). Chuẩn hoá Min-Max về khoảng [0, 1]. Giá trị 60 sau chuẩn hoá bằng bao nhiêu?","given":["min = 10 ; max = 110","new_min = 0 ; new_max = 1","v = 60"],"opts":["0,545","0,600","0,500","0,455"],"ans":[2],"sol":["v' = (v − min)/(max − min)·(new_max − new_min) + new_min","v' = (60 − 10)/(110 − 10) = 50/100","50/100 = 0,500","Kết quả: 0,500"],"kq":"0,500","note":"Đáp án 0,455 là lỗi lấy 50/110 (quên trừ min ở mẫu); 0,600 là lỗi lấy 60/100."},{"id":"ex-mm-02","topic":"Min-Max","level":1,"q":"Một khách hàng có thu nhập thấp nhất trong tập mẫu là 5 triệu, cao nhất là 10 triệu. Thu nhập 8 triệu sau khi chuẩn hoá Min-Max về [0, 1] bằng bao nhiêu?","given":["min = 5 ; max = 10","new_min = 0 ; new_max = 1","v = 8"],"opts":["3,000","0,400","0,800","0,600"],"ans":[3],"sol":["v' = (v − min)/(max − min) = (8 − 5)/(10 − 5)","= 3/5","3/5 = 0,600","Kết quả: 0,600"],"kq":"0,600","note":"Đây là câu 17 trong bộ đề chẩn đoán, đổi số. Đáp án 0,800 là lỗi bỏ bước trừ min."},{"id":"ex-mm-05","topic":"Min-Max","level":1,"q":"Cột dữ liệu có min = 20 và max = 60. Chuẩn hoá Min-Max về [0, 1]. Giá trị 35 sau chuẩn hoá bằng bao nhiêu?","given":["min = 20 ; max = 60","new_min = 0 ; new_max = 1","v = 35"],"opts":["0,250","0,583","0,375","0,625"],"ans":[2],"sol":["v' = (v − min)/(max − min)","v' = (35 − 20)/(60 − 20) = 15/40","15/40 = 0,375","Kết quả: 0,375"],"kq":"0,375","note":"0,583 là lỗi bỏ bước trừ min ở tử số; 0,625 là lỗi lấy (max − v)/(max − min) — đảo chiều."},{"id":"ex-mm-03","topic":"Min-Max","level":2,"q":"Sau khi chuẩn hoá Min-Max về [0, 1], một bản ghi có giá trị 0,35. Biết min = 20 và max = 80 của cột dữ liệu gốc, giá trị gốc của bản ghi là bao nhiêu?","given":["v' = 0,35","min = 20 ; max = 80","new_min = 0 ; new_max = 1"],"opts":["41","28","21","59"],"ans":[0],"sol":["Từ v' = (v − min)/(max − min) suy ra v = v'·(max − min) + min","v = 0,35·(80 − 20) + 20 = 0,35·60 + 20","= 21 + 20","Kết quả: 41"],"kq":"41","note":"Đáp án 21 là lỗi quên cộng lại min; 28 là lỗi lấy 0,35·80."},{"id":"ex-mm-06","topic":"Min-Max","level":2,"q":"Doanh thu ngày của một cửa hàng có min = 20 (triệu) và max = 160 (triệu). Sau khi chuẩn hoá Min-Max về [0, 1], doanh thu 48 triệu trở thành bao nhiêu?","given":["min = 20 ; max = 160","new_min = 0 ; new_max = 1","v = 48"],"opts":["0,300","0,200","0,175","0,800"],"ans":[1],"sol":["v' = (48 − 20)/(160 − 20)","= 28/140","= 0,200","Kết quả: 0,200"],"kq":"0,200","note":"0,300 là lỗi bỏ bước trừ min (48/160); 0,800 là lỗi đảo chiều."},{"id":"ex-mm-07","topic":"Min-Max","level":2,"q":"Một bản ghi có giá trị 0,72 sau khi chuẩn hoá Min-Max về [0, 1]. Biết cột dữ liệu gốc có min = 15 và max = 65, giá trị gốc là bao nhiêu?","given":["v' = 0,72","min = 15 ; max = 65"],"opts":["51","47","36","15"],"ans":[0],"sol":["v = v'·(max − min) + min","v = 0,72·(65 − 15) + 15 = 0,72·50 + 15","= 36 + 15","Kết quả: 51"],"kq":"51","note":"36 là lỗi quên cộng min; 47 là lỗi cộng nhầm (36 + 11)."},{"id":"ex-mm-04","topic":"Min-Max","level":3,"q":"Chuẩn hoá Min-Max cột Giá trị (min = 50, max = 200) về khoảng mới [0,1 ; 0,9]. Giá trị 75 sau chuẩn hoá bằng bao nhiêu?","given":["min = 50 ; max = 200","new_min = 0,1 ; new_max = 0,9","v = 75"],"opts":["0,167","0,233","0,150","0,833"],"ans":[1],"sol":["Tỉ lệ trong khoảng cũ: r = (75 − 50)/(200 − 50) = 25/150 = 0,167","v' = new_min + r·(new_max − new_min) = 0,1 + 0,167·0,8","= 0,1 + 0,133","Kết quả: 0,233"],"kq":"0,233","note":"Khoảng mới không phải [0,1] thì phải nhân thêm (new_max − new_min) rồi cộng new_min; quên bước này ra 0,167."},{"id":"ex-mm-08","topic":"Min-Max","level":3,"q":"Hai cột được chuẩn hoá Min-Max riêng về [0, 1]: Thu nhập (min 10, max 110) và Tuổi (min 20, max 60). Một khách hàng có thu nhập 80 và tuổi 35. Sau chuẩn hoá, giá trị nào lớn hơn và lớn hơn bao nhiêu?","given":["Thu nhập: min = 10 ; max = 110 ; v = 80","Tuổi: min = 20 ; max = 60 ; v = 35"],"opts":["0,375","1,075","0,700","0,325"],"ans":[3],"sol":["Thu nhập: v' = (80 − 10)/(110 − 10) = 70/100 = 0,700","Tuổi: v' = (35 − 20)/(60 − 20) = 15/40 = 0,375","Thu nhập lớn hơn: 0,700 − 0,375 = 0,325","Kết quả: 0,325"],"kq":"0,325","note":"Đây là toàn bộ mục đích của chuẩn hoá: đưa hai đơn vị khác nhau về cùng thang [0,1] để so sánh được. 1,075 là lỗi cộng thay vì trừ."},{"id":"ex-z-01","topic":"Z-Score","level":1,"q":"Một cột dữ liệu có trung bình μ = 70 và độ lệch chuẩn σ = 10. Giá trị v = 85 sau chuẩn hoá Z-Score bằng bao nhiêu?","given":["μ = 70","σ = 10","v = 85"],"opts":["0,150","−1,500","1,500","15,000"],"ans":[2],"sol":["z = (v − μ)/σ","z = (85 − 70)/10 = 15/10","15/10 = 1,500","Kết quả: 1,500"],"kq":"1,500","note":"Đáp án 15,000 là lỗi quên chia cho σ; 0,150 là lỗi chia cho σ² = 100."},{"id":"ex-z-05","topic":"Z-Score","level":1,"q":"Cột điểm có μ = 30 và σ = 4. Tính z-score của giá trị v = 41.","given":["μ = 30 ; σ = 4","v = 41"],"opts":["0,688","−2,750","2,750","11,000"],"ans":[2],"sol":["z = (v − μ)/σ","z = (41 − 30)/4 = 11/4","= 2,750","Kết quả: 2,750"],"kq":"2,750","note":"11,000 là lỗi quên chia σ; 0,688 là lỗi chia cho σ² = 16."},{"id":"ex-z-02","topic":"Z-Score","level":2,"q":"Giao dịch của một chủ thẻ có giá trị trung bình μ = 240 (nghìn đồng) và σ = 20. Một giao dịch trị giá 312. Hỏi z-score của giao dịch này bằng bao nhiêu?","given":["μ = 240 ; σ = 20","v = 312","Ngưỡng outlier của môn học: |z| > 3"],"opts":["−0,180","72,000","−3,600","3,600"],"ans":[3],"sol":["z = (312 − 240)/20","= 72/20","= 3,600","Vì |3,600| > 3 nên giao dịch bị coi là outlier tiềm năng","Kết quả: 3,600"],"kq":"3,600","note":"Slide dùng ngưỡng 3 lần độ lệch chuẩn. Đáp án −0,180 là lỗi chia cho σ² = 400."},{"id":"ex-z-04","topic":"Z-Score","level":2,"q":"Sau chuẩn hoá Z-Score, một bản ghi có z = 2,5. Biết μ = 40 và σ = 6, giá trị gốc của bản ghi là bao nhiêu?","given":["z = 2,5","μ = 40 ; σ = 6"],"opts":["25","55","42,5","15"],"ans":[1],"sol":["Từ z = (v − μ)/σ suy ra v = z·σ + μ","v = 2,5·6 + 40 = 15 + 40","= 55","Kết quả: 55"],"kq":"55","note":"Đáp án 15 là lỗi quên cộng μ; 42,5 là lỗi quên nhân σ; 25 là lỗi đảo dấu z."},{"id":"ex-z-06","topic":"Z-Score","level":2,"q":"Số dư tài khoản có μ = 8000 (nghìn đồng) và σ = 600. Một tài khoản có số dư 9200. Tính z-score và cho biết giá trị này có phải outlier tiềm năng không (ngưỡng |z| > 3).","given":["μ = 8000 ; σ = 600","v = 9200","Ngưỡng outlier: |z| > 3"],"opts":["3","2,000","1,2","0,5"],"ans":[1],"sol":["z = (9200 − 8000)/600","= 1200/600 = 2,000","|2,000| = 2 < 3 nên KHÔNG phải outlier tiềm năng","Kết quả: 2,000"],"kq":"2,000","note":"Đáp án 3 là lỗi tính 1200/400 hoặc nhầm ngưỡng; 0,5 là lỗi chia cho max."},{"id":"ex-z-03","topic":"Z-Score","level":3,"q":"Cho dãy giá trị: 12; 15; 18; 21; 24. Dùng độ lệch chuẩn tổng thể σ = √(Σ(vᵢ − μ)²/N), tính z-score của giá trị 24.","given":["Dãy: 12; 15; 18; 21; 24 (N = 5)","σ = √(Σ(vᵢ − μ)²/N)"],"opts":["1,414","6,000","4,243","−1,414"],"ans":[0],"sol":["μ = (12 + 15 + 18 + 21 + 24)/5 = 90/5 = 18","Độ lệch bình phương: 36 + 9 + 0 + 9 + 36 = 90 ⇒ phương sai = 90/5 = 18","σ = √18 ≈ 4,243","z = (24 − 18)/4,243 = 6/4,243 = 1,414","Kết quả: 1,414"],"kq":"1,414","note":"Phải chia phương sai cho N (tổng thể) chứ không phải N − 1. Đáp án 6,000 là lỗi quên chia."},{"id":"ex-z-07","topic":"Z-Score","level":3,"q":"Sau chuẩn hoá Z-Score, một bản ghi có z = -1,2. Biết μ = 75 và σ = 15, giá trị gốc của bản ghi bằng bao nhiêu?","given":["z = -1,2","μ = 75 ; σ = 15"],"opts":["57","18","60","93"],"ans":[0],"sol":["Từ z = (v − μ)/σ suy ra v = z·σ + μ","v = (-1,2)·15 + 75 = -18 + 75","= 57","Kết quả: 57"],"kq":"57","note":"93 là lỗi bỏ dấu âm của z; 18 là lỗi quên cộng μ."},{"id":"ex-z-08","topic":"Z-Score","level":3,"q":"Cho dãy giá trị: 3; 7; 8; 10. Tính z-score của giá trị 10, dùng độ lệch chuẩn tổng thể σ = √(Σ(vᵢ − μ)²/N).","given":["Dãy: 3; 7; 8; 10 (N = 4)","σ = √(Σ(vᵢ − μ)²/N)"],"opts":["2,550","3,000","0,750","1,177"],"ans":[3],"sol":["μ = (3 + 7 + 8 + 10)/4 = 28/4 = 7","Độ lệch bình phương: 16 + 0 + 1 + 9 = 26 ⇒ phương sai = 26/4 = 6,500","σ = √6,500 ≈ 2,550","z = (10 − 7)/2,550 = 1,177","Kết quả: 1,177"],"kq":"1,177","note":"Nếu chia phương sai cho N − 1 = 3 thì σ ≈ 2,944 và z ≈ 1,019 — đó là bẫy. Đề đã ghi rõ dùng N."},{"id":"ex-ds-01","topic":"Decimal Scaling","level":1,"q":"Thuộc tính có giá trị tuyệt đối lớn nhất là 923. Dùng Decimal Scaling v' = v/10^j với j là số nguyên dương nhỏ nhất để mọi |v'| < 1, giá trị 923 sau chuẩn hoá bằng bao nhiêu?","given":["max|v| = 923","v' = v/10^j ; |v'| < 1"],"opts":["0,092","923","0,923","9,230"],"ans":[2],"sol":["Với j = 2: 923/100 = 9,230 ≥ 1 nên không hợp lệ","Với j = 3: 923/1000 = 0,923 < 1 nên j = 3 là nhỏ nhất","v' = 923/1000","Kết quả: 0,923"],"kq":"0,923","note":"Điều kiện là chia đến khi max|v'| < 1, nên j phụ thuộc số chữ số phần nguyên của max."},{"id":"ex-ds-04","topic":"Decimal Scaling","level":1,"q":"Thuộc tính có giá trị tuyệt đối lớn nhất bằng 476. Áp dụng Decimal Scaling v' = v/10^j với j nhỏ nhất sao cho |v'| < 1. Giá trị 476 sau chuẩn hoá bằng bao nhiêu?","given":["max|v| = 476","v' = v/10^j ; |v'| < 1"],"opts":["4,760","0,048","0,476","47,600"],"ans":[2],"sol":["j = 1: 47,600 ≥ 1 ; j = 2: 4,760 ≥ 1 ; j = 3: 0,476 < 1","Vậy j = 3 là nhỏ nhất thoả điều kiện","v' = 476/1000","Kết quả: 0,476"],"kq":"0,476","note":"Chỉ cần chia 100 là chưa đủ vì 4,760 vẫn lớn hơn 1. Bẫy thường gặp là đếm thiếu một chữ số."},{"id":"ex-ds-05","topic":"Decimal Scaling","level":1,"q":"Cho dãy 5,7; 2,3; 0,8. Dùng Decimal Scaling với j nhỏ nhất để mọi giá trị sau chuẩn hoá có trị tuyệt đối nhỏ hơn 1. Giá trị 2,3 sau chuẩn hoá bằng bao nhiêu?","given":["Dãy: 5,7; 2,3; 0,8","v' = v/10^j ; |v'| < 1"],"opts":["0,570","0,230","0,023","2,300"],"ans":[1],"sol":["max|v| = 5,7 ⇒ j = 1 cho 5,7/10 = 0,570 < 1, hợp lệ","Áp dụng cùng j = 1: v' = v/10","2,3/10 = 0,230","Kết quả: 0,230"],"kq":"0,230","note":"Đáp án 0,570 là lỗi trả giá trị 5,7 (giá trị lớn nhất) thay vì 2,3."},{"id":"ex-ds-02","topic":"Decimal Scaling","level":2,"q":"Cho dãy giá trị 45; 12; 68. Dùng Decimal Scaling với j là số nguyên dương nhỏ nhất để mọi giá trị sau chuẩn hoá có trị tuyệt đối nhỏ hơn 1. Giá trị 45 sau chuẩn hoá bằng bao nhiêu?","given":["Dãy: 45; 12; 68","v' = v/10^j ; |v'| < 1"],"opts":["4,500","45,0","0,045","0,450"],"ans":[3],"sol":["max|v| = 68 ⇒ j = 1 cho 6,800 ≥ 1 nên phải lấy j = 2","Kiểm tra: 68/100 = 0,680 < 1, hợp lệ","v' = 45/100","Kết quả: 0,450"],"kq":"0,450","note":"Phải tìm j từ giá trị LỚN NHẤT của dãy (68), rồi áp dụng CÙNG j cho mọi giá trị, kể cả 45 và 12."},{"id":"ex-ds-06","topic":"Decimal Scaling","level":2,"q":"Cho dãy 3,42; 0,87; 2,10. Tìm j nhỏ nhất cho Decimal Scaling (mọi |v'| < 1) rồi tính giá trị 0,87 sau chuẩn hoá.","given":["Dãy: 3,42; 0,87; 2,10","v' = v/10^j ; |v'| < 1"],"opts":["0,087","0,870","0,342","0,009"],"ans":[0],"sol":["max|v| = 3,42 ⇒ j = 0 không được vì 3,42 ≥ 1; j = 1 cho 0,342 < 1","Vậy j = 1","v' = 0,87/10 = 0,087","Kết quả: 0,087"],"kq":"0,087","note":"0,870 là lỗi quên chia (giữ nguyên giá trị); 0,0087 là lỗi lấy j = 2 (thừa một bậc)."},{"id":"ex-ds-07","topic":"Decimal Scaling","level":2,"q":"Cho dãy 456; 23; 891. Sau khi Decimal Scaling với j nhỏ nhất (mọi |v'| < 1), tổng ba giá trị đã chuẩn hoá bằng bao nhiêu?","given":["Dãy: 456; 23; 891","v' = v/10^j ; |v'| < 1"],"opts":["0,137","13,700","1370,000","1,370"],"ans":[3],"sol":["max|v| = 891 ⇒ j = 3 (891/1000 = 0,891 < 1)","456/1000 = 0,456 ; 23/1000 = 0,023 ; 891/1000 = 0,891","Tổng = 0,456 + 0,023 + 0,891 = 1,370","Kết quả: 1,370"],"kq":"1,370","note":"Tổng các giá trị đã chuẩn hoá không bắt buộc < 1; chỉ TỪNG giá trị phải < 1. 1370 là lỗi quên chia."},{"id":"ex-ds-03","topic":"Decimal Scaling","level":3,"q":"Cho dãy giá trị 0,92; 12,4; 3,5. Hỏi j nhỏ nhất (số nguyên dương) để sau Decimal Scaling mọi giá trị đều có trị tuyệt đối nhỏ hơn 1?","given":["Dãy: 0,92; 12,4; 3,5","v' = v/10^j ; |v'| < 1"],"opts":["2","4","3","1"],"ans":[0],"sol":["max|v| = 12,4","j = 1: 12,4/10 = 1,240 ≥ 1 nên chưa đạt","j = 2: 12,4/100 = 0,124 < 1 nên đạt; các giá trị khác cũng < 1","Kết quả: j = 2"],"kq":"j = 2","note":"Bẫy: 12,4 chỉ có 2 chữ số phần nguyên nhưng j phải là 2 chứ không phải 1, vì 12,4/10 vẫn lớn hơn 1."},{"id":"ex-ew-01","topic":"Equal-width Binning","level":1,"q":"Ngân hàng chia khách hàng thành 3 nhóm theo Equal-width Binning. Hạn mức thấp nhất là 100 triệu, cao nhất là 700 triệu. Độ rộng mỗi khoảng bằng bao nhiêu triệu đồng?","given":["min = 100 ; max = 700","k = 3 khoảng"],"opts":["233,333","200","600","300"],"ans":[1],"sol":["w = (max − min)/k","w = (700 − 100)/3 = 600/3","= 200","Kết quả: 200 triệu đồng"],"kq":"200 triệu đồng","note":"Đây là câu 18 của bộ đề chẩn đoán đổi số. Đáp án 600 là lỗi quên chia cho k."},{"id":"ex-ew-05","topic":"Equal-width Binning","level":1,"q":"Dữ liệu có min = 4 và max = 40. Áp dụng Equal-width Binning chia thành 4 khoảng có độ rộng bằng nhau. Độ rộng mỗi khoảng là bao nhiêu?","given":["min = 4 ; max = 40","k = 4 khoảng"],"opts":["36","44","9","10"],"ans":[2],"sol":["w = (max − min)/k","w = (40 − 4)/4 = 36/4","= 9","Kết quả: w = 9"],"kq":"w = 9","note":"36 là lỗi quên chia k; 10 là lỗi chia cho k + 0,4 hoặc nhầm max = 40; 44 là lỗi cộng max + min."},{"id":"ex-ew-02","topic":"Equal-width Binning","level":2,"q":"Dữ liệu có min = 15 và max = 63. Dùng Equal-width Binning chia thành 3 khoảng có độ rộng bằng nhau. Độ rộng mỗi khoảng w bằng bao nhiêu?","given":["min = 15 ; max = 63","k = 3"],"opts":["78","12","16","48"],"ans":[2],"sol":["w = (63 − 15)/3","= 48/3","= 16","Kết quả: w = 16"],"kq":"w = 16","note":"48 là lỗi quên chia k; 12 là lỗi chia cho k + 1; 78 là lỗi cộng max + min."},{"id":"ex-ew-03","topic":"Equal-width Binning","level":2,"q":"Dữ liệu có min = 20 và max = 92. Dùng Equal-width Binning chia thành 4 khoảng có độ rộng bằng nhau, đánh số khoảng từ 1. Giá trị 70 rơi vào khoảng thứ mấy?","given":["min = 20 ; max = 92","k = 4","Khoảng 1 là [20; 38)"],"opts":["4","1","2","3"],"ans":[3],"sol":["w = (92 − 20)/4 = 72/4 = 18","Các khoảng: [20;38) ; [38;56) ; [56;74) ; [74;92]","70 nằm trong [56; 74)","Kết quả: khoảng thứ 3"],"kq":"khoảng thứ 3","note":"Công thức nhanh: chỉ số khoảng = ⌊(v − min)/w⌋ + 1 = ⌊(70 − 20)/18⌋ + 1 = 2 + 1 = 3."},{"id":"ex-ew-06","topic":"Equal-width Binning","level":2,"q":"Dữ liệu điểm từ 0 đến 100. Áp dụng Equal-width Binning chia thành 5 khoảng có độ rộng bằng nhau, đánh số khoảng từ 1. Điểm 63 rơi vào khoảng thứ mấy?","given":["min = 0 ; max = 100","k = 5","Khoảng 1 là [0; 20)"],"opts":["3","4","5","2"],"ans":[1],"sol":["w = (100 − 0)/5 = 20","Các khoảng: [0;20) ; [20;40) ; [40;60) ; [60;80) ; [80;100]","63 nằm trong [60; 80)","Kết quả: khoảng thứ 4"],"kq":"khoảng thứ 4","note":"Công thức nhanh: ⌊(63 − 0)/20⌋ + 1 = 3 + 1 = 4. Đáp án 3 là lỗi quên cộng 1."},{"id":"ex-ew-04","topic":"Equal-width Binning","level":3,"q":"Dữ liệu có min = 12 và max = 60. Dùng Equal-width Binning chia thành 4 khoảng có độ rộng bằng nhau. Giá trị 47 nằm trong một khoảng; biên dưới của khoảng đó bằng bao nhiêu?","given":["min = 12 ; max = 60","k = 4"],"opts":["36","48","12","24"],"ans":[0],"sol":["w = (60 − 12)/4 = 48/4 = 12","Các khoảng: [12;24) ; [24;36) ; [36;48) ; [48;60]","47 thuộc [36; 48) nên biên dưới là 36","Kết quả: 36"],"kq":"36","note":"Đáp án 48 là lỗi lấy biên trên; 24 và 12 là biên dưới của các khoảng khác."},{"id":"ex-ew-07","topic":"Equal-width Binning","level":3,"q":"Dữ liệu có min = 50 và max = 90. Áp dụng Equal-width Binning chia thành 4 khoảng có độ rộng bằng nhau, đánh số từ 1. Biên trên của khoảng thứ 3 bằng bao nhiêu?","given":["min = 50 ; max = 90","k = 4"],"opts":["80","75","60","70"],"ans":[0],"sol":["w = (90 − 50)/4 = 40/4 = 10","Các khoảng: [50;60) ; [60;70) ; [70;80) ; [80;90]","Khoảng 3 là [70; 80) nên biên trên = 80","Kết quả: 80"],"kq":"80","note":"Công thức: biên trên khoảng i = min + i·w = 50 + 3·10 = 80. Đáp án 70 là biên DƯỚI của khoảng 3."},{"id":"ex-ew-08","topic":"Equal-width Binning","level":4,"q":"Doanh thu từ 30 đến 150 (triệu). Áp dụng Equal-width Binning chia thành 6 khoảng có độ rộng bằng nhau, đánh số từ 1. Giá trị 125 thuộc khoảng thứ mấy và khoảng đó có dạng [a; b) với a bằng bao nhiêu?","given":["min = 30 ; max = 150","k = 6","Khoảng 1 là [30; 50)"],"opts":["khoảng 6, a = 130","khoảng 4, a = 90","khoảng 5, a = 120","khoảng 5, a = 110"],"ans":[3],"sol":["w = (150 − 30)/6 = 120/6 = 20","Biên các khoảng: 30, 50, 70, 90, 110, 130, 150","125 nằm giữa 110 và 130 nên thuộc khoảng 5","a = min + ⌊(125 − 30)/20⌋·20 = 30 + 4·20 = 110","Kết quả: khoảng 5, a = 110"],"kq":"khoảng 5, a = 110","note":"⌊95/20⌋ = 4 nên chỉ số khoảng = 4 + 1 = 5. Đáp án a = 120 là lỗi làm tròn 125/20 = 6,25 rồi nhân."},{"id":"ex-ef-01","topic":"Equal-frequency Binning","level":1,"q":"Một thuộc tính có 10 bản ghi được chia thành 2 khoảng theo Equal-frequency Binning. Mỗi khoảng chứa bao nhiêu bản ghi?","given":["N = 10 bản ghi","k = 2 khoảng"],"opts":["2","5","10","3"],"ans":[1],"sol":["Equal-frequency chia sao cho mỗi khoảng có số bản ghi bằng nhau","Số bản ghi mỗi khoảng = N/k","= 10/2 = 5","Kết quả: 5 bản ghi"],"kq":"5 bản ghi","note":"Đáp án 10 là lỗi trả tổng số bản ghi; 2 là lỗi trả số khoảng."},{"id":"ex-ef-06","topic":"Equal-frequency Binning","level":1,"q":"Một thuộc tính có 36 bản ghi được chia thành 4 khoảng theo Equal-frequency Binning. Mỗi khoảng chứa bao nhiêu bản ghi?","given":["N = 36 bản ghi","k = 4 khoảng"],"opts":["4","144","9","36"],"ans":[2],"sol":["Equal-frequency chia đều SỐ BẢN GHI cho mỗi khoảng","Số bản ghi mỗi khoảng = N/k","= 36/4 = 9","Kết quả: 9 bản ghi"],"kq":"9 bản ghi","note":"Đáp án 4 là lỗi trả số khoảng k; 144 là lỗi nhân thay vì chia."},{"id":"ex-ef-02","topic":"Equal-frequency Binning","level":2,"q":"Dữ liệu đã sắp tăng: 4; 7; 8; 9; 12; 15; 18; 20; 23; 26; 29; 33. Chia thành 3 khoảng theo Equal-frequency Binning. Khoảng thứ hai chứa những giá trị nào?","given":["Dãy 12 giá trị: 4; 7; 8; 9; 12; 15; 18; 20; 23; 26; 29; 33","k = 3 khoảng"],"opts":["20; 23; 26; 29","15; 18; 20; 23","12; 15; 18; 20","12; 15; 18"],"ans":[2],"sol":["Số bản ghi mỗi khoảng = 12/3 = 4","Khoảng 1: 4; 7; 8; 9","Khoảng 2: 12; 15; 18; 20","Khoảng 3: 23; 26; 29; 33","Kết quả: 12; 15; 18; 20"],"kq":"12; 15; 18; 20","note":"Equal-frequency đếm SỐ BẢN GHI, không chia đều độ rộng giá trị. Đáp án 12; 15; 18 là lỗi chia 4 phần tử cho 3 khoảng."},{"id":"ex-ef-03","topic":"Equal-frequency Binning","level":2,"q":"Dãy 16 giá trị đã sắp tăng: 7; 11; 15; 18; 22; 25; 29; 31; 35; 38; 43; 46; 49; 52; 55; 60. Chia thành 4 khoảng theo Equal-frequency Binning. Giá trị lớn nhất trong khoảng thứ ba là bao nhiêu?","given":["Dãy 16 giá trị: 7; 11; 15; 18; 22; 25; 29; 31; 35; 38; 43; 46; 49; 52; 55; 60","k = 4 khoảng"],"opts":["43","31","49","46"],"ans":[3],"sol":["Số bản ghi mỗi khoảng = 16/4 = 4","Khoảng 3 gồm phần tử thứ 9 đến 12: 35; 38; 43; 46","Giá trị lớn nhất của khoảng 3 = 46","Kết quả: 46"],"kq":"46","note":"43 là phần tử thứ 11 (lỗi lệch 1 vị trí); 31 là biên trên khoảng 2; 49 là phần tử đầu khoảng 4."},{"id":"ex-ef-07","topic":"Equal-frequency Binning","level":2,"q":"Dãy 12 giá trị đã sắp tăng: 5; 9; 12; 16; 19; 23; 27; 30; 34; 38; 41; 45. Chia thành 3 khoảng theo Equal-frequency Binning. Giá trị lớn nhất trong khoảng thứ hai là bao nhiêu?","given":["Dãy 12 giá trị: 5; 9; 12; 16; 19; 23; 27; 30; 34; 38; 41; 45","k = 3 khoảng"],"opts":["23","30","27","34"],"ans":[1],"sol":["Số bản ghi mỗi khoảng = 12/3 = 4","Khoảng 1: 5; 9; 12; 16","Khoảng 2: 19; 23; 27; 30 ⇒ lớn nhất = 30","Khoảng 3: 34; 38; 41; 45","Kết quả: 30"],"kq":"30","note":"27 là phần tử thứ 7 (lỗi lệch 1 vị trí); 34 là phần tử đầu khoảng 3."},{"id":"ex-ef-10","topic":"Equal-frequency Binning","level":2,"q":"Dãy 12 giá trị đã sắp tăng: 4; 9; 11; 15; 18; 22; 27; 31; 36; 40; 45; 52. Chia thành 4 khoảng theo Equal-frequency Binning. Giá trị trung bình (mean) của khoảng chứa số 36 là bao nhiêu?","given":["Dãy 12 giá trị: 4; 9; 11; 15; 18; 22; 27; 31; 36; 40; 45; 52","k = 4 khoảng"],"opts":["33,500","36,000","31,333","35,667"],"ans":[2],"sol":["Số bản ghi mỗi khoảng = 12/4 = 3","Khoảng 1: 4; 9; 11 — Khoảng 2: 15; 18; 22","Khoảng 3: 27; 31; 36 — Khoảng 4: 40; 45; 52","36 nằm ở khoảng 3, mean = (27 + 31 + 36)/3 = 31,333","Kết quả: 31,333"],"kq":"31,333","note":"Câu này nối hai bước: chia bin rồi tính mean trong bin (trị số đại diện khi làm mượt bằng binning). Đáp án 36,000 là lỗi trả nguyên giá trị; (31+36+40)/3 là lỗi lệch một vị trí."},{"id":"ex-ef-05","topic":"Equal-frequency Binning","level":3,"q":"Dãy 10 giá trị đã sắp tăng: 1; 1; 2; 2; 3; 3; 4; 5; 50; 100. Chia thành 2 khoảng theo Equal-frequency Binning. Khoảng thứ hai chứa những giá trị nào?","given":["Dãy 10 giá trị: 1; 1; 2; 2; 3; 3; 4; 5; 50; 100","k = 2 khoảng"],"opts":["1; 1; 2; 2; 3","3; 4; 5; 50; 100","4; 5; 50; 100","3; 4; 5"],"ans":[1],"sol":["Số bản ghi mỗi khoảng = 10/2 = 5","Khoảng 1: 1; 1; 2; 2; 3","Khoảng 2: 3; 4; 5; 50; 100","Kết quả: 3; 4; 5; 50; 100"],"kq":"3; 4; 5; 50; 100","note":"Giá trị 3 xuất hiện ở cả hai khoảng vì equal-frequency đếm bản ghi. Đáp án 3; 4; 5 là lỗi loại 50 và 100 vì coi là outlier."},{"id":"ex-ef-08","topic":"Equal-frequency Binning","level":3,"q":"Dãy 12 giá trị đã sắp tăng: 1; 1; 2; 3; 3; 3; 4; 4; 5; 5; 6; 9. Chia thành 3 khoảng theo Equal-frequency Binning. Khoảng thứ hai chứa những giá trị nào?","given":["Dãy 12 giá trị: 1; 1; 2; 3; 3; 3; 4; 4; 5; 5; 6; 9","k = 3 khoảng"],"opts":["3; 3; 4; 4","2; 3; 3; 3","4; 4; 5; 5","3; 3; 3; 4"],"ans":[0],"sol":["Số bản ghi mỗi khoảng = 12/3 = 4","Khoảng 1 (phần tử 1–4): 1; 1; 2; 3","Khoảng 2 (phần tử 5–8): 3; 3; 4; 4","Khoảng 3 (phần tử 9–12): 5; 5; 6; 9","Kết quả: 3; 3; 4; 4"],"kq":"3; 3; 4; 4","note":"Giá trị 3 xuất hiện ở cả khoảng 1 và khoảng 2 vì equal-frequency đếm bản ghi, không đếm giá trị phân biệt. Phương án 4;4;5;5 là lỗi lệch một vị trí."},{"id":"ex-ef-04","topic":"Equal-frequency Binning","level":4,"q":"Dữ liệu lệch: 1; 1; 2; 2; 3; 3; 4; 5; 50; 100. Chia thành 5 khoảng theo Equal-frequency Binning rồi làm mượt bằng cách thay mỗi giá trị bằng trung bình cộng các giá trị trong khoảng của nó. Sau khi làm mượt, giá trị 50 trở thành bao nhiêu?","given":["Dãy 10 giá trị: 1; 1; 2; 2; 3; 3; 4; 5; 50; 100","k = 5 khoảng","Làm mượt: thay v bằng mean của bin chứa v"],"opts":["75","50","150","37,5"],"ans":[0],"sol":["Số bản ghi mỗi khoảng = 10/5 = 2","Các khoảng: [1;1] ; [2;2] ; [3;3] ; [4;5] ; [50;100]","50 nằm ở khoảng thứ năm, mean = (50 + 100)/2 = 75","Kết quả: 75"],"kq":"75","note":"150 là lỗi quên chia cho số phần tử của bin; 50 là lỗi quên làm mượt; 37,5 là lỗi chia mean thêm một lần nữa."},{"id":"ex-ef-09","topic":"Equal-frequency Binning","level":4,"q":"Dữ liệu lệch: 1; 1; 2; 2; 3; 3; 4; 4; 5; 6; 80; 151. Chia thành 3 khoảng theo Equal-frequency Binning. Khoảng thứ ba (khoảng giá trị lớn nhất) chứa những giá trị nào?","given":["Dãy 12 giá trị: 1; 1; 2; 2; 3; 3; 4; 4; 5; 6; 80; 151","k = 3 khoảng"],"opts":["1; 1; 2; 2","3; 3; 4; 4","5; 6; 80","5; 6; 80; 151"],"ans":[3],"sol":["Số bản ghi mỗi khoảng = 12/3 = 4","Khoảng 1: 1; 1; 2; 2 — Khoảng 2: 3; 3; 4; 4","Khoảng 3: 5; 6; 80; 151 (đủ 4 bản ghi như hai khoảng kia)","Kết quả: 5; 6; 80; 151"],"kq":"5; 6; 80; 151","note":"Đáp án 5; 6; 80 là lỗi loại 151 vì coi là outlier. Đây chính là điểm mạnh của Equal-frequency so với Equal-width: cùng dữ liệu này, Equal-width (min 1, max 151, k = 3, w = 50) dồn 10 bản ghi vào khoảng [1;51) và để khoảng [51;101) rỗng."},{"id":"ex-sma-01","topic":"SMA","level":1,"q":"Giá dầu 6 ngày liên tiếp: 75, 78, 76, 80, 82, 81 (USD). Với kích thước cửa sổ <b>k = 3</b>, SMA của Ngày 4 bằng bao nhiêu?","given":["Ngày 1: 75 · Ngày 2: 78 · Ngày 3: 76","Ngày 4: 80 · Ngày 5: 82 · Ngày 6: 81","k = 3"],"opts":["76,33","79,33","80,00","78,00"],"ans":[3],"sol":["SMA tại Ngày 4 lấy trung bình của k = 3 ngày GẦN NHẤT tính đến Ngày 4: Ngày 2, 3, 4.","Cửa sổ = (78 + 76 + 80) / 3","= 234 / 3","Kết quả: 78,00 USD"],"kq":"78,00 USD","note":"Bẫy hay gặp: lấy nhầm cửa sổ Ngày 1–3 → (75+78+76)/3 = 76,33. SMA Ngày 4 phải <b>kết thúc</b> ở Ngày 4, không phải bắt đầu từ Ngày 1."},{"id":"ex-sma-02","topic":"SMA","level":2,"q":"Doanh thu 6 tháng: 10, 12, 14, 16, 18, 20 (tỷ đồng). Với <b>k = 2</b>, SMA của tháng 5 bằng bao nhiêu?","given":["Tháng 1–6: 10 · 12 · 14 · 16 · 18 · 20","k = 2"],"opts":["16,00","17,00","18,00","15,00"],"ans":[1],"sol":["k = 2 → lấy trung bình 2 tháng gần nhất tính đến tháng 5: tháng 4 và tháng 5.","Cửa sổ = (16 + 18) / 2","= 34 / 2","Kết quả: 17,00 tỷ đồng"],"kq":"17,00 tỷ đồng","note":"Với k = 2, SMA luôn là trung điểm của hai giá trị liền trước và hiện tại. Đáp án 15,00 là lấy nhầm cửa sổ tháng 3–4; 16,00 và 18,00 là quên chia trung bình."},{"id":"ex-sma-04","topic":"SMA","level":2,"q":"Nhiệt độ 7 ngày: 50, 52, 54, 56, 58, 60, 62 (°C). Với <b>k = 4</b>, SMA của ngày 5 bằng bao nhiêu?","given":["Ngày 1–7: 50 · 52 · 54 · 56 · 58 · 60 · 62","k = 4"],"opts":["53,00","55,00","56,00","54,50"],"ans":[1],"sol":["k = 4 → lấy 4 ngày gần nhất tính đến ngày 5: ngày 2, 3, 4, 5 → giá trị 52, 54, 56, 58.","Cửa sổ = (52 + 54 + 56 + 58) / 4","= 220 / 4","Kết quả: 55,00 °C"],"kq":"55,00 °C","note":"Với dãy cách đều, SMA rơi đúng vào giá trị giữa của cửa sổ — dùng tính chất này để kiểm nhanh. Đáp án 53,00 là cửa sổ ngày 1–4 (lệch một ngày); 54,50 là cộng đủ 4 số nhưng chia 4 sai chỗ."},{"id":"ex-sma-08","topic":"SMA","level":2,"q":"Chuỗi 6 giá trị: 12, 15, 11, 18, 14, 20. Với <b>k = 4</b>, SMA của ngày 6 bằng bao nhiêu?","given":["Ngày 1–6: 12 · 15 · 11 · 18 · 14 · 20","k = 4"],"opts":["17,33","15,75","14,50","14,00"],"ans":[1],"sol":["k = 4 → dùng ngày 3, 4, 5, 6: giá trị 11, 18, 14, 20.","Cửa sổ = (11 + 18 + 14 + 20) / 4","= 63 / 4","Kết quả: 15,75"],"kq":"15,75","note":"Ba nhiễu ứng ba lỗi điển hình: <b>14,50</b> = cửa sổ ngày 2–5 (lệch một ngày); <b>14,00</b> = cửa sổ ngày 1–4 (lệch hai ngày); <b>17,33</b> = dùng nhầm k = 3 với ngày 4–6 → (18+14+20)/3. Luôn đếm đúng số phần tử trong cửa sổ rồi mới chia."},{"id":"ex-sma-03","topic":"SMA","level":3,"q":"Lượng truy cập 7 ngày: 100, 110, 120, 90, 95, 105, 115 (nghìn lượt). Với <b>k = 3</b>, SMA của ngày 6 bằng bao nhiêu?","given":["Ngày 1–7: 100 · 110 · 120 · 90 · 95 · 105 · 115","k = 3"],"opts":["105,00","95,00","96,67","101,67"],"ans":[2],"sol":["SMA ngày 6 lấy 3 ngày gần nhất tính đến ngày 6: ngày 4, 5, 6 → giá trị 90, 95, 105.","Cửa sổ = (90 + 95 + 105) / 3","= 290 / 3","= 96,666… → làm tròn 96,67","Kết quả: 96,67 nghìn lượt"],"kq":"96,67 nghìn lượt","note":"Ba phương án nhiễu là cửa sổ lệch một ngày: 101,67 = ngày 3–5; 105,00 = ngày 5–7; 95,00 = chỉ lấy giá trị ngày 5. Luôn đếm lại chỉ số ngày trước khi cộng."},{"id":"ex-sma-06","topic":"SMA","level":3,"q":"Chuỗi 8 ngày: 20, 22, 24, 26, 28, 30, 32, 34. SMA với k = 3 của ngày 8 trừ SMA với k = 3 của ngày 7 bằng bao nhiêu?","given":["Ngày 1–8: 20 · 22 · 24 · 26 · 28 · 30 · 32 · 34","k = 3"],"opts":["0,67","2,00","1,00","4,00"],"ans":[1],"sol":["SMA ngày 7 = (28 + 30 + 32) / 3 = 90 / 3 = 30,00","SMA ngày 8 = (30 + 32 + 34) / 3 = 96 / 3 = 32,00","Chênh lệch = 32,00 − 30,00","Kết quả: 2,00"],"kq":"2,00","note":"Với dãy cách đều bước d, SMA cũng cách đều bước d (ở đây d = 2) — nên chênh lệch đúng bằng 2,00. Nhiễu <b>0,67</b> = lấy 2 chia cho k = 3; <b>4,00</b> = lấy bước giá trị gốc × 2; <b>1,00</b> = nhầm bước của dãy là 1."},{"id":"ex-sma-05","topic":"SMA","level":4,"q":"Giá cổ phiếu 6 ngày: 75, 78, 76, 80, 82, 81 (nghìn đồng). Ngày nào là ngày <b>sớm nhất</b> tính được SMA với k = 3, và giá trị SMA ngày đó bằng bao nhiêu?","given":["Ngày 1–6: 75 · 78 · 76 · 80 · 82 · 81","k = 3"],"opts":["Ngày 1, SMA = 75,00","Ngày 2, SMA = 76,50","Ngày 3, SMA = 76,33","Ngày 4, SMA = 78,00"],"ans":[2],"sol":["SMA cần đủ k điểm dữ liệu. Với k = 3, ngày sớm nhất có đủ 3 điểm là ngày 3 (dùng ngày 1, 2, 3).","Cửa sổ ngày 3 = (75 + 78 + 76) / 3","= 229 / 3 = 76,333…","Kết quả: Ngày 3, SMA = 76,33"],"kq":"Ngày 3, SMA = 76,33","note":"Có <b>k − 1</b> ngày đầu không tính được SMA — với k = 3 thì ngày 1 và ngày 2 bị bỏ trống, nên chuỗi SMA luôn ngắn hơn chuỗi gốc đúng k − 1 điểm. Phương án \"Ngày 4, SMA = 78,00\" có giá trị số ĐÚNG nhưng sai ngày: (78+76+80)/3 = 78,00 là SMA ngày 4, không phải ngày sớm nhất."},{"id":"ex-sma-07","topic":"SMA","level":4,"q":"Doanh thu 5 tháng: 100, 200, 300, 400, 500 (triệu). Dùng <b>k = 3</b>, dự báo doanh thu tháng 6 theo phương pháp \"SMA của tháng gần nhất\" là bao nhiêu?","given":["Tháng 1–5: 100 · 200 · 300 · 400 · 500","k = 3"],"opts":["400,00","450,00","500,00","300,00"],"ans":[0],"sol":["Dự báo tháng 6 = SMA của 3 tháng gần nhất đã biết, tức tháng 3, 4, 5.","Cửa sổ = (300 + 400 + 500) / 3","= 1200 / 3","Kết quả: 400,00 triệu"],"kq":"400,00 triệu","note":"Dự báo SMA luôn <b>trễ</b> so với xu hướng đang tăng: doanh thu thực tháng 5 đã là 500 nhưng dự báo chỉ 400. Đây chính là nhược điểm của SMA — càng tăng nhanh thì dự báo càng bị kéo về sau."},{"id":"ex-apr-01","topic":"Apriori","level":1,"q":"Có 5 item đơn lẻ đều đã thỏa Minsup. Hỏi bước sinh ứng viên của Apriori phải tạo ra bao nhiêu itemset gồm 2 phần tử để đem đi kiểm tra?","given":["Số item phổ biến bậc 1: n = 5","Cần sinh tập ứng viên bậc 2 (C2)"],"opts":["20","25","10","12,5"],"ans":[2],"sol":["Số itemset 2 phần tử chọn từ n item là C(n,2) = n·(n−1)/2","= 5·4/2 = 10","Vậy C2 có 10 ứng viên cần đếm support","Kết quả: 10 itemset"],"kq":"10 itemset","note":"Slide ghi xấp xỉ n²/2 = 12,5 nhưng đó chỉ là ước lượng; số đúng là C(5,2) = 10. Ra 20 là đã đếm cả hai thứ tự."},{"id":"ex-apr-05","topic":"Apriori","level":1,"q":"Cho cơ sở dữ liệu giao dịch sau với Minsup = 4 (tính theo support count). Sau khi đếm support count bậc 1 và sinh các ứng viên bậc 2, có bao nhiêu tập phổ biến bậc 2?","given":["T1: a, b, c","T2: a, b, d","T3: a, c, d","T4: b, c, d","T5: a, b, c, d","T6: a, b","T7: a, b, c","Minsup = 4 (support count)"],"opts":["6","3","1","4"],"ans":[1],"sol":["Đếm bậc 1: a = 6, b = 6, c = 5, d = 4 → cả 4 item đều ≥ 4 nên đều phổ biến","Sinh C2 từ 4 item: C(4,2) = 6 ứng viên","Đếm support count: {a,b} = 5; {a,c} = 4; {a,d} = 3; {b,c} = 4; {b,d} = 3; {c,d} = 3","Giữ các cặp ≥ 4: {a,b}, {a,c}, {b,c}","Kết quả: 3 tập"],"kq":"3 tập","note":"Ra 6 là quên bước tỉa theo Minsup. Ra 1 là dùng dấu > thay vì ≥ nên chỉ còn {a,b} = 5."},{"id":"ex-apr-02","topic":"Apriori","level":2,"q":"Cho cơ sở dữ liệu giao dịch sau với Minsup = 3 (tính theo support count). Sau khi sinh các ứng viên bậc 2 từ các item phổ biến bậc 1 rồi đếm support count, có bao nhiêu tập phổ biến bậc 2?","given":["T1: p, q, r","T2: p, q","T3: p, r, s","T4: q, r, s","T5: p, q, s","T6: p, r","T7: p, q, r, s","T8: q, s","T9: p, q, r","T10: r, s","Minsup = 3 (support count)"],"opts":["5","6","4","10"],"ans":[1],"sol":["Đếm bậc 1: p = 7, q = 7, r = 7, s = 6 → cả 4 item đều phổ biến","Sinh C2 từ 4 item: C(4,2) = 6 ứng viên","Đếm: {p,q} = 5; {p,r} = 5; {p,s} = 3; {q,r} = 4; {q,s} = 4; {r,s} = 4","Cả 6 ứng viên đều ≥ 3, kể cả {p,s} đúng bằng 3","Kết quả: 6 tập phổ biến bậc 2"],"kq":"6 tập","note":"Điều kiện là ≥ Minsup nên {p,s} = 3 vẫn được giữ. Ra 5 là đã dùng dấu > thay vì ≥."},{"id":"ex-apr-06","topic":"Apriori","level":2,"q":"Cho cơ sở dữ liệu giao dịch sau với Minsup = 3 (support count). Tổng số tập phổ biến ở tất cả các kích thước là bao nhiêu?","given":["T1: p, q, r","T2: p, q","T3: p, r, s","T4: q, r, s","T5: p, q, s","T6: p, r","T7: p, q, r, s","T8: q, s","T9: p, q, r","T10: r, s","Minsup = 3 (support count)"],"opts":["10","7","15","11"],"ans":[3],"sol":["Bậc 1: p = 7, q = 7, r = 7, s = 6 → 4 tập phổ biến","Bậc 2: pq = 5, pr = 5, ps = 3, qr = 4, qs = 4, rs = 4 → 6 tập","Bậc 3: chỉ {p,q,r} có count = 3 ≥ 3; các bộ ba khác đều ≤ 2 → 1 tập","Bậc 4: {p,q,r,s} chỉ có 2 giao dịch nên không phổ biến","Tổng = 4 + 6 + 1 = 11","Kết quả: 11 tập phổ biến"],"kq":"11 tập","note":"15 = 2⁴ − 1 là tổng số tập con khác rỗng, không phải số tập phổ biến. 10 là quên tập bậc 3."},{"id":"ex-apr-03","topic":"Apriori","level":3,"q":"Cho cơ sở dữ liệu giao dịch sau với Minsup = 3 (support count). Biết tập phổ biến bậc 2 gồm đúng 9 tập: {a,b}, {a,c}, {a,d}, {a,e}, {b,c}, {b,d}, {c,d}, {c,e}, {d,e}. Khi sinh ứng viên bậc 3 bằng cách ghép hai tập bậc 2 có cùng item đầu (chưa làm bước tỉa), thu được bao nhiêu ứng viên?","given":["T1: a, b, c, d","T2: a, b, c","T3: a, b, e","T4: a, c, d, e","T5: b, c, d","T6: a, b, c, d, e","T7: c, d, e","T8: a, b, d","Minsup = 3 (support count)","F2 = {a,b}, {a,c}, {a,d}, {a,e}, {b,c}, {b,d}, {c,d}, {c,e}, {d,e}"],"opts":["7","10","5","8"],"ans":[3],"sol":["Ghép các cặp F2 cùng item đầu tiên:","Nhóm a: {a,b}+{a,c}→abc; {a,b}+{a,d}→abd; {a,b}+{a,e}→abe; {a,c}+{a,d}→acd; {a,c}+{a,e}→ace; {a,d}+{a,e}→ade","Nhóm b: {b,c}+{b,d}→bcd","Nhóm c: {c,d}+{c,e}→cde","Cộng lại: 6 + 1 + 1 = 8 ứng viên","Kết quả: 8 ứng viên C3"],"kq":"8 ứng viên","note":"Nếu ra 7 là đã làm luôn bước tỉa: {a,b,e} bị loại vì tập con {b,e} không có trong F2. Còn 5 là số tập phổ biến bậc 3 thực sự."},{"id":"ex-apr-07","topic":"Apriori","level":3,"q":"Cho cơ sở dữ liệu giao dịch sau với Minsup = 4 (support count). Có bao nhiêu tập phổ biến bậc 3?","given":["T1: a, b, c","T2: a, b, d","T3: a, c, d","T4: b, c, d","T5: a, b, c, d","T6: a, b","T7: a, b, c","Minsup = 4 (support count)"],"opts":["0","1","3","7"],"ans":[0],"sol":["F2 = {a,b} = 5, {a,c} = 4, {b,c} = 4 → 3 tập phổ biến bậc 2","Ghép các cặp cùng item đầu: {a,b} + {a,c} → {a,b,c}; đó là ứng viên C3 duy nhất","Đếm support count của {a,b,c}: T1, T5, T7 → 3","3 < Minsup = 4 nên {a,b,c} không phổ biến; không còn ứng viên bậc 3 nào khác","Kết quả: 0 tập phổ biến bậc 3"],"kq":"0 tập","note":"Ra 1 là đếm số ứng viên sinh ra chứ không kiểm tra support count. Ra 7 là tổng số tập phổ biến của mọi kích thước."},{"id":"ex-apr-04","topic":"Apriori","level":4,"q":"Cho cơ sở dữ liệu giao dịch sau với Minsup = 3 (support count). Tổng số tập phổ biến thu được ở tất cả các kích thước (k = 1 đến 5) là bao nhiêu?","given":["T1: a, b, c, d","T2: a, b, c","T3: a, b, e","T4: a, c, d, e","T5: b, c, d","T6: a, b, c, d, e","T7: c, d, e","T8: a, b, d","Minsup = 3 (support count)"],"opts":["19","14","9","31"],"ans":[0],"sol":["Bậc 1: a = 6, b = 6, c = 6, d = 6, e = 4 → 5 tập phổ biến","Bậc 2: ab = 5, ac = 4, ad = 4, ae = 3, bc = 4, bd = 4, cd = 5, ce = 3, de = 3 → 9 tập","Bậc 3: abc = 3, abd = 3, acd = 3, bcd = 3, cde = 3 → 5 tập","Bậc 4: mọi bộ 4 item đều có support count ≤ 2 (ví dụ abcd đếm được 2) nên không có tập nào; bậc 5 cũng vậy","Tổng = 5 + 9 + 5 = 19","Kết quả: 19 tập phổ biến"],"kq":"19 tập","note":"2^5 − 1 = 31 là tổng số tập con khác rỗng, không phải số tập phổ biến. 14 là quên cộng F3."},{"id":"ex-sup-01","topic":"Support-Confidence","level":1,"q":"Cho cơ sở dữ liệu giao dịch sau. Độ hỗ trợ (Support) của luật kết hợp {c} → {d} bằng bao nhiêu?","given":["T1: a, b, c, d","T2: a, b, c","T3: a, b, e","T4: a, c, d, e","T5: b, c, d","T6: a, b, c, d, e","T7: c, d, e","T8: a, b, d"],"opts":["0,833","0,750","0,625","0,375"],"ans":[2],"sol":["Đếm số giao dịch chứa đồng thời c và d: T1, T4, T5, T6, T7 → 5 giao dịch","Tổng số giao dịch: |D| = 8","Sup({c} → {d}) = 5/8 = 0,625","Kết quả: 0,625"],"kq":"0,625","note":"Support luôn chia cho TỔNG số giao dịch (8), không chia cho số giao dịch chứa {c}. Chia cho 6 sẽ ra 0,833 là Confidence."},{"id":"ex-sup-04","topic":"Support-Confidence","level":1,"q":"Cho cơ sở dữ liệu giao dịch sau. Độ tin cậy (Confidence) của luật {q} → {s} bằng bao nhiêu?","given":["T1: p, q, r","T2: p, q","T3: p, r, s","T4: q, r, s","T5: p, q, s","T6: p, r","T7: p, q, r, s","T8: q, s","T9: p, q, r","T10: r, s"],"opts":["0,400","0,667","0,571","0,952"],"ans":[2],"sol":["Đếm giao dịch chứa cả q và s: T4, T5, T7, T8 → 4","Đếm giao dịch chứa tiền đề q: T1, T2, T4, T5, T7, T8, T9 → 7","Conf = count({q,s}) / count({q}) = 4/7 = 0,571","Kết quả: 0,571"],"kq":"0,571","note":"Mẫu số là số giao dịch chứa TIỀN ĐỀ q (7), không phải tổng 10. Chia cho 10 sẽ ra 0,400 là Support."},{"id":"ex-sup-02","topic":"Support-Confidence","level":2,"q":"Cho cơ sở dữ liệu giao dịch sau. Độ tin cậy (Confidence) của luật {a, b} → {d} bằng bao nhiêu?","given":["T1: a, b, c, d","T2: a, b, c","T3: a, b, e","T4: a, c, d, e","T5: b, c, d","T6: a, b, c, d, e","T7: c, d, e","T8: a, b, d"],"opts":["0,600","0,375","0,500","0,800"],"ans":[0],"sol":["Số giao dịch chứa cả a, b, d: T1, T6, T8 → 3","Số giao dịch chứa tiền đề {a, b}: T1, T2, T3, T6, T8 → 5","Conf = count({a,b,d}) / count({a,b}) = 3/5 = 0,600","Kết quả: 0,600"],"kq":"0,600"},{"id":"ex-sup-05","topic":"Support-Confidence","level":2,"q":"Cho cơ sở dữ liệu giao dịch sau. Độ tin cậy (Confidence) của luật {p, q} → {r} bằng bao nhiêu?","given":["T1: p, q, r","T2: p, q","T3: p, r, s","T4: q, r, s","T5: p, q, s","T6: p, r","T7: p, q, r, s","T8: q, s","T9: p, q, r","T10: r, s"],"opts":["0,300","0,600","0,429","0,857"],"ans":[1],"sol":["Đếm giao dịch chứa cả p, q, r: T1, T7, T9 → 3","Đếm giao dịch chứa tiền đề {p,q}: T1, T2, T5, T7, T9 → 5","Conf = 3/5 = 0,600","Kết quả: 0,600"],"kq":"0,600","note":"0,429 là lấy 3 chia cho count(p) = 7, tức chia sai mẫu số. 0,300 là Support, không phải Confidence."},{"id":"ex-sup-06","topic":"Support-Confidence","level":3,"q":"Cho cơ sở dữ liệu giao dịch sau, dùng minsup = 0,4 (theo support) và minconf = 0,7. Chỉ xét các luật dạng một item → một item, có bao nhiêu luật thỏa mãn đồng thời cả hai ngưỡng?","given":["T1: p, q, r","T2: p, q","T3: p, r, s","T4: q, r, s","T5: p, q, s","T6: p, r","T7: p, q, r, s","T8: q, s","T9: p, q, r","T10: r, s","minsup = 0,4 · minconf = 0,7"],"opts":["10","6","5","4"],"ans":[3],"sol":["minsup 0,4 trên 10 giao dịch tương đương support count ≥ 4","Các cặp đạt: pq = 5, pr = 5, qr = 4, qs = 4, rs = 4 → sinh ra 10 luật có hướng (ps = 3 bị loại)","Conf các luật: p→q = 5/7 = 0,714; p→r = 5/7 = 0,714; q→p = 0,714; r→p = 0,714 (đạt)","Các luật còn lại: q→r = 4/7 = 0,571; q→s = 0,571; r→q = 0,571; r→s = 0,571; s→q = 4/6 = 0,667; s→r = 0,667 (đều dưới 0,7)","Kết quả: 4 luật (p→q, p→r, q→p, r→p)"],"kq":"4 luật","note":"10 là số luật chỉ lọc qua minsup. 5 là số cặp không hướng chứ không phải số luật."},{"id":"ex-sup-03","topic":"Support-Confidence","level":4,"q":"Cho cơ sở dữ liệu giao dịch sau, dùng minsup = 0,4 (theo support) và minconf = 0,8. Chỉ xét các luật dạng một item → một item, có bao nhiêu luật thỏa mãn đồng thời cả hai ngưỡng?","given":["T1: a, b, c, d","T2: a, b, c","T3: a, b, e","T4: a, c, d, e","T5: b, c, d","T6: a, b, c, d, e","T7: c, d, e","T8: a, b, d","minsup = 0,4 · minconf = 0,8"],"opts":["2","4","6","12"],"ans":[1],"sol":["minsup 0,4 trên 8 giao dịch tương đương support count ≥ 3,2, tức ≥ 4","Các cặp đạt: {a,b} = 5, {a,c} = 4, {a,d} = 4, {b,c} = 4, {b,d} = 4, {c,d} = 5 → 6 cặp","Xét 12 luật có hướng sinh ra từ 6 cặp này, Conf = count(X∪Y)/count(X)","Đạt 0,8: {a}→{b} = 5/6 = 0,833; {b}→{a} = 5/6 = 0,833; {c}→{d} = 5/6 = 0,833; {d}→{c} = 5/6 = 0,833","Tám luật còn lại đều chỉ đạt 4/6 = 0,667 < 0,8","Kết quả: 4 luật"],"kq":"4 luật","note":"12 là số luật chỉ lọc qua minsup; 6 là số cặp chứ không phải số luật; 2 là chỉ đếm được 2 cặp mạnh nhất."},{"id":"ex-lift-01","topic":"Lift-Leverage","level":1,"q":"Cho cơ sở dữ liệu giao dịch sau. Tính độ nâng (Lift) của luật {d} → {e}.","given":["T1: a, b, c, d","T2: a, b, c","T3: a, b, e","T4: a, c, d, e","T5: b, c, d","T6: a, b, c, d, e","T7: c, d, e","T8: a, b, d"],"opts":["0,500","0,375","0,750","1,000"],"ans":[3],"sol":["Đếm: c(d,e) = 3 (T4, T6, T7); c(d) = 6; c(e) = 4; |D| = 8","Sup(X∪Y) = 3/8 = 0,375; Sup(X) = 6/8 = 0,750; Sup(Y) = 4/8 = 0,500","Lift = 0,375 / (0,750 · 0,500) = 0,375 / 0,375 = 1,000","Kết quả: 1,000"],"kq":"1,000","note":"Lift = 1 nghĩa là tiền đề và hậu đề độc lập, không có tác động lẫn nhau. 0,500 chính là Confidence, 0,375 là Support."},{"id":"ex-lift-04","topic":"Lift-Leverage","level":1,"q":"Cho cơ sở dữ liệu giao dịch sau. Tính độ nâng (Lift) của luật {a} → {b}.","given":["T1: a, b, c, d","T2: a, b, c","T3: a, b, e","T4: a, c, d, e","T5: b, c, d","T6: a, b, c, d, e","T7: c, d, e","T8: a, b, d"],"opts":["1,111","0,833","0,625","0,563"],"ans":[0],"sol":["Đếm: c(a,b) = 5; c(a) = 6; c(b) = 6; |D| = 8","Sup(X∪Y) = 5/8 = 0,625; Sup(X) = 6/8 = 0,750; Sup(Y) = 6/8 = 0,750","Lift = 0,625 / (0,750 · 0,750) = 0,625 / 0,5625 = 1,111","Kết quả: 1,111"],"kq":"1,111","note":"0,833 là Confidence (5/6); 0,625 là Support; 0,563 là Sup(X)·Sup(Y) — mới là mẫu số, chưa chia."},{"id":"ex-lift-02","topic":"Lift-Leverage","level":2,"q":"Cho cơ sở dữ liệu giao dịch sau. Tính độ nâng (Lift) của luật {b} → {e}.","given":["T1: a, b, c, d","T2: a, b, c","T3: a, b, e","T4: a, c, d, e","T5: b, c, d","T6: a, b, c, d, e","T7: c, d, e","T8: a, b, d"],"opts":["0,333","0,667","0,250","0,444"],"ans":[1],"sol":["Đếm: c(b,e) = 2 (T3, T6); c(b) = 6; c(e) = 4; |D| = 8","Sup(X∪Y) = 2/8 = 0,250; Sup(X) = 6/8 = 0,750; Sup(Y) = 4/8 = 0,500","Lift = 0,250 / (0,750 · 0,500) = 0,250 / 0,375 = 0,667","Kết quả: 0,667"],"kq":"0,667","note":"Lift < 1 nên tiền đề làm giảm khả năng xảy ra hậu đề. 0,333 là Confidence (2/6); 0,444 là khi lấy nhầm Sup(b) cho cả hai vế."},{"id":"ex-lift-05","topic":"Lift-Leverage","level":2,"q":"Cho cơ sở dữ liệu giao dịch sau. Tính độ đòn bẩy (Leverage) của luật {a} → {b}, biết Leverage = Sup(X∪Y) − Sup(X)·Sup(Y).","given":["T1: a, b","T2: a, b","T3: a, c","T4: d, e","T5: d, f","Leverage = Sup(X∪Y) − Sup(X)·Sup(Y)"],"opts":["0,240","0,400","0,160","1,667"],"ans":[2],"sol":["Đếm: c(a,b) = 2; c(a) = 3; c(b) = 2; |D| = 5","Sup(X∪Y) = 2/5 = 0,400; Sup(X) = 3/5 = 0,600; Sup(Y) = 2/5 = 0,400","Sup(X)·Sup(Y) = 0,600 · 0,400 = 0,240","Leverage = 0,400 − 0,240 = 0,160","Kết quả: 0,160"],"kq":"0,160","note":"0,240 là tích Sup(X)·Sup(Y) — quên trừ. 0,400 là Support. 1,667 là Lift, một thang đo khác."},{"id":"ex-lift-03","topic":"Lift-Leverage","level":3,"q":"Cho cơ sở dữ liệu giao dịch sau. Tính độ nâng (Lift) của luật {a} → {b} và cho biết mức tăng so với ngẫu nhiên.","given":["T1: a, b","T2: a, b","T3: a, b","T4: c, d","T5: c, e","T6: d, e"],"opts":["2,000","1,000","0,500","0,250"],"ans":[0],"sol":["Đếm: c(a) = 3, c(b) = 3, c(a,b) = 3; |D| = 6","Sup(X∪Y) = 3/6 = 0,500; Sup(X) = 3/6 = 0,500; Sup(Y) = 3/6 = 0,500","Lift = 0,500 / (0,500 · 0,500) = 0,500 / 0,250 = 2,000","Kết quả: 2,000"],"kq":"2,000","note":"Confidence = 1,000 (3/3, luật tuyệt đối đúng) nhưng Lift = 2,000 mới cho biết mức tăng gấp đôi so với ngẫu nhiên. 0,250 là Sup(X)·Sup(Y)."},{"id":"ex-lift-06","topic":"Lift-Leverage","level":3,"q":"Cho cơ sở dữ liệu giao dịch sau. Tính độ nâng (Lift) của luật {c} → {d, e}, tức X = {c} và Y = {d, e}.","given":["T1: a, b, c, d","T2: a, b, c","T3: a, b, e","T4: a, c, d, e","T5: b, c, d","T6: a, b, c, d, e","T7: c, d, e","T8: a, b, d"],"opts":["0,500","1,333","0,375","1,000"],"ans":[1],"sol":["Đếm: c(c,d,e) = 3 (T4, T6, T7); c(c) = 6; c(d,e) = 3; |D| = 8","Sup(X∪Y) = 3/8 = 0,375; Sup(X) = 6/8 = 0,750; Sup(Y) = 3/8 = 0,375","Lift = 0,375 / (0,750 · 0,375) = 0,375 / 0,28125 = 1,333","Kết quả: 1,333"],"kq":"1,333","note":"0,500 là Confidence (3/6). 1,000 là lấy 0,375 chia cho Sup(d,e) = 0,375, tức bỏ qua Sup(X)."},{"id":"ex-fp-01","topic":"FP-Growth","level":1,"q":"Cho cơ sở dữ liệu giao dịch sau với Minsup = 3 (support count). Theo quy ước của FP-Growth, các item đạt ngưỡng được sắp theo thứ tự nào trước khi chèn vào FP-tree?","given":["T1: a, b, c, d, e","T2: a, b, c, d","T3: a, b, c, d","T4: a, b, c","T5: a, b, e","T6: a","Minsup = 3 (support count)"],"opts":["a, b, c, d, e","d, c, b, a","a, b, c, d","a, b, c"],"ans":[2],"sol":["Đếm support count: a = 6, b = 5, c = 4, d = 3, e = 2","e = 2 < 3 nên bị loại khỏi danh sách item phổ biến","Sắp giảm dần theo support count: a (6), b (5), c (4), d (3)","Kết quả: a, b, c, d"],"kq":"a, b, c, d","note":"Thứ tự cố định này rất quan trọng: {a,b,c} là itemset hợp lệ, còn {c,b,a} là không hợp lệ. Giữ e là quên lọc theo Minsup."},{"id":"ex-fp-02","topic":"FP-Growth","level":2,"q":"Cho cơ sở dữ liệu giao dịch sau với Minsup = 3 (support count). Có bao nhiêu tập phổ biến gồm 2 item?","given":["T1: a, b, c, d, e","T2: a, b, c, d","T3: a, b, c, d","T4: a, b, c","T5: a, b, e","T6: a","Minsup = 3 (support count)"],"opts":["3","10","4","6"],"ans":[3],"sol":["Chỉ các item a, b, c, d đạt Minsup nên chỉ xét các cặp trong 4 item này","Đếm: ab = 5; ac = 4; ad = 3; bc = 4; bd = 3; cd = 3","Cả 6 cặp đều có support count ≥ 3","Kết quả: 6 tập"],"kq":"6 tập","note":"Ra 3 là đã dùng dấu > thay vì ≥ nên bỏ mất ad, bd, cd (đều bằng 3). Ra 10 là tính cả item e đã bị loại."},{"id":"ex-fp-04","topic":"FP-Growth","level":2,"q":"Cho cơ sở dữ liệu giao dịch sau với Minsup = 3 (support count). Có bao nhiêu item bị loại khỏi danh sách item phổ biến trong bước tiền xử lý của FP-Growth?","given":["T1: a, b, c, d, e","T2: a, b, c, d","T3: a, b, c","T4: a, b, c","T5: a, b","T6: a, b, e","T7: a, c","Minsup = 3 (support count)"],"opts":["3","5","0","2"],"ans":[3],"sol":["Đếm support count từng item: a = 7, b = 6, c = 5, d = 2, e = 2","Item đạt Minsup ≥ 3: a, b, c → 3 item được giữ","Item dưới ngưỡng: d = 2 và e = 2 → bị loại","Kết quả: 2 item bị loại"],"kq":"2 item","note":"Ra 3 là đếm số item ĐƯỢC GIỮ; ra 5 là tổng số item khác nhau trong dữ liệu."},{"id":"ex-fp-05","topic":"FP-Growth","level":2,"q":"Cho cơ sở dữ liệu giao dịch sau với Minsup = 3 (support count). Theo FP-Growth, Condition Pattern Base của item d chỉ có một đường tiền tố là {a, b, c} với số lần xuất hiện 3. Vậy support count của tập {a, b, c, d} bằng bao nhiêu?","given":["T1: a, b, c, d, e","T2: a, b, c, d","T3: a, b, c, d","T4: a, b, c","T5: a, b, e","T6: a","Minsup = 3 (support count)","CPB(d) = {a, b, c} : 3"],"opts":["3","4","5","6"],"ans":[0],"sol":["Condition Pattern Base của d chứa các đường tiền tố đi kèm nút d, kèm số lần xuất hiện","Đường tiền tố duy nhất là {a,b,c} với count = 3","Support count của {a,b,c,d} chính là số lần đường tiền tố đó xuất hiện, tức 3","Kiểm tra trực tiếp: {a,b,c,d} có trong T1, T2, T3 → đúng 3 giao dịch","Kết quả: 3"],"kq":"3","note":"4 là count của {a,b,c}, 5 là count của {a,b}, 6 là count của {a} — đây là lỗi lấy count của tiền tố thay vì của cả itemset."},{"id":"ex-fp-03","topic":"FP-Growth","level":3,"q":"Cho cơ sở dữ liệu giao dịch sau với Minsup = 3 (support count). Tổng số tập phổ biến ở tất cả các kích thước là bao nhiêu?","given":["T1: a, b, c, d, e","T2: a, b, c, d","T3: a, b, c, d","T4: a, b, c","T5: a, b, e","T6: a","Minsup = 3 (support count)"],"opts":["10","15","8","6"],"ans":[1],"sol":["Bậc 1: a = 6, b = 5, c = 4, d = 3, e = 2 → {a}, {b}, {c}, {d} = 4 tập","Bậc 2: ab = 5, ac = 4, ad = 3, bc = 4, bd = 3, cd = 3 → 6 tập","Bậc 3: abc = 4, abd = 3, acd = 3, bcd = 3 → 4 tập","Bậc 4: abcd = 3 → 1 tập","Tổng = 4 + 6 + 4 + 1 = 15","Kết quả: 15 tập phổ biến"],"kq":"15 tập","note":"Dùng dấu > thay cho ≥ sẽ mất các tập có count đúng bằng 3 và chỉ còn 8. Ra 10 là quên cộng F3 và F4."},{"id":"ex-fp-06","topic":"FP-Growth","level":3,"q":"Cho cơ sở dữ liệu giao dịch sau với Minsup = 3 (support count). Tổng số tập phổ biến ở tất cả các kích thước là bao nhiêu?","given":["T1: a, b, c, d, e","T2: a, b, c, d","T3: a, b, c","T4: a, b, c","T5: a, b","T6: a, b, e","T7: a, c","Minsup = 3 (support count)"],"opts":["6","19","7","3"],"ans":[2],"sol":["Đếm bậc 1: a = 7, b = 6, c = 5, d = 2, e = 2 → chỉ a, b, c phổ biến = 3 tập","Bậc 2 (chỉ xét a, b, c): ab = 6, ac = 5, bc = 4 → 3 tập","Bậc 3: abc = 4 ≥ 3 → 1 tập","Tổng = 3 + 3 + 1 = 7","Kết quả: 7 tập phổ biến"],"kq":"7 tập","note":"6 là quên tập bậc 3 {a,b,c}. 19 là kết quả khi hạ Minsup xuống 2, tức tính sai ngưỡng."},{"id":"ex-pr-04","topic":"PageRank","level":1,"q":"Cho đồ thị liên kết sau. Với d = 0,85 và PageRank khởi tạo bằng 1, giá trị PageRank của B ở vòng lặp đầu tiên là bao nhiêu? Công thức: PR(n) = 1 − d + d·Σ PR(m)/C(m).","given":["Cạnh: A → B","Cạnh: A → C","Cạnh: B → C","Cạnh: C → B","d = 0,85 · PR khởi tạo = 1"],"opts":["0,575","1,425","1,275","0,150"],"ans":[1],"sol":["Out-degree: C(A) = 2, C(B) = 1, C(C) = 1","B nhận liên kết từ A (góp 1/2 = 0,5) và từ C (góp 1/1 = 1)","Σ PR(m)/C(m) = 0,5 + 1 = 1,5","PR(B) = 1 − 0,85 + 0,85 · 1,5 = 0,15 + 1,275 = 1,425","Kết quả: 1,425"],"kq":"1,425","note":"0,575 là chỉ tính một trong hai in-link (quên C → B). 1,275 là quên cộng phần 1 − d = 0,15."},{"id":"ex-pr-01","topic":"PageRank","level":2,"q":"Cho đồ thị liên kết sau. Với hệ số damping d = 0,85, PageRank khởi tạo của mọi trang bằng 1. Giá trị PageRank của B ở vòng lặp đầu tiên là bao nhiêu? Công thức: PR(n) = 1 − d + d·Σ PR(m)/C(m).","given":["Cạnh: A → B","Cạnh: A → C","Cạnh: B → C","Cạnh: C → A","d = 0,85 · PR khởi tạo = 1"],"opts":["0,575","1,000","1,425","0,850"],"ans":[0],"sol":["Out-degree: C(A) = 2, C(B) = 1, C(C) = 1","B chỉ nhận liên kết từ A, mà C(A) = 2 nên tổng đóng góp = 1/2 = 0,5","PR(B) = 1 − 0,85 + 0,85 · 0,5 = 0,15 + 0,425","Kết quả: 0,575"],"kq":"0,575","note":"1,425 là giá trị của C, không phải của B. 0,850 là đã quên cộng phần 1 − d = 0,15."},{"id":"ex-pr-02","topic":"PageRank","level":2,"q":"Cho đồ thị liên kết sau. Với d = 0,85 và PageRank khởi tạo bằng 1, giá trị PageRank của C ở vòng lặp đầu tiên là bao nhiêu? Công thức: PR(n) = 1 − d + d·Σ PR(m)/C(m).","given":["Cạnh: A → B","Cạnh: A → C","Cạnh: B → C","Cạnh: C → A","d = 0,85 · PR khởi tạo = 1"],"opts":["0,575","1,275","1,425","1,000"],"ans":[2],"sol":["Out-degree: C(A) = 2, C(B) = 1, C(C) = 1","C nhận liên kết từ A và từ B: A đóng góp 1/2 = 0,5; B đóng góp 1/1 = 1","Σ PR(m)/C(m) = 0,5 + 1 = 1,5","PR(C) = 0,15 + 0,85 · 1,5 = 0,15 + 1,275","Kết quả: 1,425"],"kq":"1,425","note":"Đừng quên chia cho out-degree C(m); nếu cộng thẳng PR(m) sẽ ra 2,85. 1,275 là thiếu phần 0,15."},{"id":"ex-pr-05","topic":"PageRank","level":2,"q":"Cho đồ thị liên kết sau. Với d = 0,85 và PageRank khởi tạo bằng 1, giá trị PageRank của A ở VÒNG LẶP THỨ HAI là bao nhiêu? Công thức: PR(n) = 1 − d + d·Σ PR(m)/C(m).","given":["Cạnh: A → B","Cạnh: B → A","Cạnh: A → C","Cạnh: C → D","Cạnh: D → B","d = 0,85 · PR khởi tạo = 1","Vòng 1: A = 1,000 ; B = 1,425 ; C = 0,575 ; D = 1,000"],"opts":["1,000","1,211","1,425","1,361"],"ans":[3],"sol":["Out-degree: C(A) = 2, C(B) = 1, C(C) = 1, C(D) = 1","A chỉ nhận liên kết từ B, nên Σ PR(m)/C(m) = PR(B)/C(B) = 1,425/1 = 1,425","PR(A) = 0,15 + 0,85 · 1,425 = 0,15 + 1,21125","Kết quả: 1,361"],"kq":"1,361","note":"1,000 là giá trị vòng 1 chưa cập nhật. 1,211 là quên cộng 0,15. 1,425 là PR của B chứ không phải của A."},{"id":"ex-pr-03","topic":"PageRank","level":3,"q":"Cho đồ thị liên kết sau. Với d = 0,85 và PageRank khởi tạo bằng 1, giá trị PageRank của D ở vòng lặp đầu tiên là bao nhiêu? Công thức: PR(n) = 1 − d + d·Σ PR(m)/C(m).","given":["Cạnh: A → B","Cạnh: A → C","Cạnh: B → D","Cạnh: C → D","Cạnh: D → A","d = 0,85 · PR khởi tạo = 1"],"opts":["1,700","1,850","1,000","0,575"],"ans":[1],"sol":["Out-degree: C(A) = 2, C(B) = 1, C(C) = 1, C(D) = 1","D nhận liên kết từ B và từ C, mỗi nguồn góp 1/1 = 1","Σ PR(m)/C(m) = 1 + 1 = 2","PR(D) = 0,15 + 0,85 · 2 = 0,15 + 1,7","Kết quả: 1,850"],"kq":"1,850","note":"Node có nhiều in-link từ các trang ít out-link sẽ nhận giá trị lớn. 1,700 là quên cộng 0,15; 0,575 là giá trị của B và C."},{"id":"ex-pr-06","topic":"PageRank","level":3,"q":"Cho đồ thị liên kết sau. Với d = 0,85 và PageRank khởi tạo bằng 1, hãy xếp hạng các trang theo PageRank giảm dần sau VÒNG LẶP THỨ HAI. Công thức: PR(n) = 1 − d + d·Σ PR(m)/C(m).","given":["Cạnh: A → B","Cạnh: A → C","Cạnh: B → C","Cạnh: B → D","Cạnh: C → A","Cạnh: D → B","d = 0,85 · PR khởi tạo = 1"],"opts":["C > B > A > D","B > A > C > D","A > B > C > D","C > A > B > D"],"ans":[0],"sol":["Out-degree: C(A) = 2, C(B) = 2, C(C) = 1, C(D) = 1","Vòng 1: A = 0,15 + 0,85·(1/1) = 1,000; B = 0,15 + 0,85·(1/2 + 1/1) = 1,425; C = 0,15 + 0,85·(1/2 + 1/2) = 1,000; D = 0,15 + 0,85·(1/2) = 0,575","Vòng 2: A = 0,15 + 0,85·(1,000/1) = 1,000; B = 0,15 + 0,85·(1,000/2 + 0,575/1) = 1,064","Vòng 2: C = 0,15 + 0,85·(1,000/2 + 1,425/2) = 1,181; D = 0,15 + 0,85·(1,425/2) = 0,756","So sánh: C = 1,181 > B = 1,064 > A = 1,000 > D = 0,756","Kết quả: C > B > A > D"],"kq":"C > B > A > D","note":"B > A > C > D là xếp hạng của vòng 1 (B = 1,425 đứng đầu). A > B > C > D là giả định theo tên đỉnh, không có cơ sở tính toán."},{"id":"ex-cpt-03","topic":"CPT","level":1,"q":"Cho tập chuỗi huấn luyện sau. Dùng cây CPT, với tiền tố «M, N» thì phần tử có điểm dự đoán cao nhất là phần tử nào và điểm đó bằng bao nhiêu lần xuất hiện?","given":["S1: M, N, O","S2: M, N, O","S3: M, N, O","S4: M, N, O","S5: M, N, O","S6: M, N, P","S7: M, N, P"],"opts":["P — 2 lần","M — 7 lần","O — 5 lần","N — 7 lần"],"ans":[2],"sol":["S1 đến S5 có «M,N» đứng ngay trước O → đếm được O: 5","S6, S7 có «M,N» đứng ngay trước P → đếm được P: 2","Điểm cao nhất là 5, thuộc về O","Kết quả: O — 5 lần"],"kq":"O (5 lần)","note":"M và N đều có 7 lần toàn cục nhưng chúng là tiền tố, không phải phần tử dự đoán."},{"id":"ex-cpt-01","topic":"CPT","level":2,"q":"Cho tập chuỗi huấn luyện sau. Dùng cây CPT, với tiền tố «Q, R» thì phần tử có điểm dự đoán cao nhất là phần tử nào và điểm đó bằng bao nhiêu lần xuất hiện?","given":["S1: P, Q, R, S","S2: P, Q, R, S","S3: P, Q, R, S","S4: P, Q, R, T","S5: P, Q, R, T"],"opts":["T — 2 lần","P — 5 lần","R — 5 lần","S — 3 lần"],"ans":[3],"sol":["S1, S2, S3 có «Q,R» đứng ngay trước S → đếm được S: 3","S4, S5 có «Q,R» đứng ngay trước T → đếm được T: 2","Điểm dự đoán cao nhất là 3, thuộc về S","Kết quả: S — 3 lần"],"kq":"S (3 lần)","note":"CPT chỉ đếm phần tử đứng NGAY SAU tiền tố, không dùng tần suất toàn cục. P và R có 5 lần toàn cục nhưng không đứng sau «Q,R» lần nào."},{"id":"ex-cpt-04","topic":"CPT","level":2,"q":"Cho tập chuỗi huấn luyện sau, trong đó chuỗi S1 và S2 chứa tiền tố «A, B» hai lần. Dùng cây CPT, khi dự đoán tiếp cho chuỗi tiền tố «A, B» thì phần tử nào có điểm dự đoán cao nhất và bằng bao nhiêu?","given":["S1: A, B, C, A, B, C","S2: A, B, C, A, B, D","S3: A, B, D","S4: A, C","CPT đếm mọi lần xuất hiện của tiền tố"],"opts":["D — 2 lần","C — 3 lần","C — 2 lần","A — 6 lần"],"ans":[1],"sol":["Liệt kê mọi lần «A,B» đứng ngay trước một phần tử:","S1: lần đầu trước C, lần sau trước C; S2: lần đầu trước C, lần sau trước D; S3: trước D","Đếm: C = 3 (S1 hai lần + S2 một lần); D = 2 (S2 một lần + S3 một lần)","Điểm cao nhất là 3, thuộc về C","Kết quả: C — 3 lần"],"kq":"C (3 lần)","note":"D — 2 lần là kết quả khi chỉ xét lần xuất hiện CUỐI trong mỗi chuỗi; C — 2 lần là khi chỉ xét lần xuất hiện ĐẦU. A — 6 lần là tần suất toàn cục của A, không dùng để dự đoán."},{"id":"ex-cpt-02","topic":"CPT","level":3,"q":"Cho tập chuỗi huấn luyện sau. Dùng cây CPT, khi dự đoán tiếp cho chuỗi tiền tố «A, B» thì phần tử nào có điểm dự đoán cao nhất và bằng bao nhiêu?","given":["S1: A, B, C, D","S2: A, B, C, D","S3: A, B, C, D","S4: D, A, B, E","S5: D, E"],"opts":["D — 5 lần","C — 3 lần","E — 1 lần","C — 1 lần"],"ans":[1],"sol":["S1, S2, S3 có «A,B» đứng ngay trước C → đếm được C: 3","S4 có «A,B» đứng ngay trước E → đếm được E: 1","D tuy xuất hiện 5 lần trong toàn bộ dữ liệu nhưng đứng sau «A,B» đúng 0 lần","Kết quả: C — 3 lần"],"kq":"C (3 lần)","note":"Bẫy hay gặp là chọn D vì D có tần suất toàn cục cao nhất (5 lần). CPT chỉ quan tâm phần tử nối tiếp tiền tố."},{"id":"ex-cpt-05","topic":"CPT","level":4,"q":"Cho tập chuỗi huấn luyện sau. Dùng CPT với quy ước: luôn lấy 2 phần tử cuối của chuỗi hiện tại làm tiền tố để dự đoán phần tử kế tiếp. Xuất phát từ chuỗi «A, B», hãy dự đoán tiếp 2 phần tử để được chuỗi có 4 phần tử.","given":["S1: A, B, C, D","S2: A, B, C, D","S3: A, B, C, E","S4: A, B, F, D","S5: A, B, F, D","Quy ước: tiền tố = 2 phần tử cuối"],"opts":["A, B, F, D","A, B, C, E","A, B, C, C","A, B, C, D"],"ans":[3],"sol":["Bước 1: tiền tố «A,B». Đếm phần tử nối tiếp: C = 3 (S1, S2, S3), F = 2 (S4, S5) → chọn C","Chuỗi hiện tại thành «A, B, C»; tiền tố mới là «B,C»","Bước 2: đếm phần tử nối tiếp sau «B,C»: S1, S2 cho D (2 lần); S3 cho E (1 lần) → chọn D","Kết quả: A, B, C, D"],"kq":"A, B, C, D","note":"A, B, F, D là chọn theo lần xuất hiện cuối của «A,B». A, B, C, C là dùng lại tiền tố «A,B» thay vì cập nhật thành «B,C»."},{"id":"ex-bfs-01","topic":"BFS-DFS","level":1,"q":"Cho đồ thị vô hướng sau. Duyệt BFS từ đỉnh A. Khi có nhiều lựa chọn, duyệt theo thứ tự bảng chữ cái. Hãy cho biết thứ tự duyệt các đỉnh.","given":["Cạnh: A — B","Cạnh: A — C","Cạnh: B — D","Cạnh: B — E","Cạnh: C — F","Cạnh: D — G","Cạnh: E — G","Nguồn: A · nhiều lựa chọn thì theo bảng chữ cái"],"opts":["A → B → D → G → E → C → F","A → C → B → F → E → D → G","A → B → C → D → E → F → G","A → C → F → B → E → G → D"],"ans":[2],"sol":["Hàng đợi ban đầu [A]. Lấy A, in A, đưa B và C vào hàng đợi theo thứ tự bảng chữ cái","Lấy B, in B, đưa D và E vào hàng đợi","Lấy C, in C, đưa F vào hàng đợi","Lấy D in D; lấy E in E; lấy F in F; lấy G in G (G đã được đánh dấu từ D)","Kết quả: A → B → C → D → E → F → G"],"kq":"A → B → C → D → E → F → G","note":"BFS duyệt theo từng mức: A ở mức 0, B và C ở mức 1, D, E, F ở mức 2, G ở mức 3. Phương án A → B → D → G → E → C → F là DFS."},{"id":"ex-bfs-02","topic":"BFS-DFS","level":2,"q":"Cho đồ thị CÓ HƯỚNG sau (chỉ đi theo chiều mũi tên). Duyệt DFS từ đỉnh A. Khi có nhiều lựa chọn, duyệt theo thứ tự bảng chữ cái. Hãy cho biết thứ tự duyệt các đỉnh.","given":["Cạnh: A → B","Cạnh: A → C","Cạnh: B → D","Cạnh: C → D","Cạnh: C → F","Cạnh: D → E","Cạnh: F → E","Nguồn: A · nhiều lựa chọn thì theo bảng chữ cái"],"opts":["A → B → D → E → C → F","A → B → C → D → F → E","A → C → F → E → D → B","A → C → B → F → D → E"],"ans":[0],"sol":["Thăm A. Các đỉnh kề của A là B và C, chọn B (bảng chữ cái)","Từ B chỉ có D nên thăm D; từ D có E nên thăm E; E không có đỉnh kề","Quay lại A, còn C nên thăm C; từ C có D (đã thăm) và F nên thăm F; F có E đã thăm","Kết quả: A → B → D → E → C → F"],"kq":"A → B → D → E → C → F","note":"DFS đi sâu hết một nhánh rồi mới quay lui. A → B → C → D → F → E là BFS vì duyệt theo mức."},{"id":"ex-bfs-03","topic":"BFS-DFS","level":2,"q":"Cho đồ thị CÓ HƯỚNG sau (chỉ đi theo chiều mũi tên). Duyệt BFS từ đỉnh A. Khi có nhiều lựa chọn, duyệt theo thứ tự bảng chữ cái. Hãy cho biết thứ tự duyệt các đỉnh.","given":["Cạnh: A → B","Cạnh: A → C","Cạnh: B → D","Cạnh: C → D","Cạnh: C → F","Cạnh: D → E","Cạnh: F → E","Nguồn: A · nhiều lựa chọn thì theo bảng chữ cái"],"opts":["A → B → C → D → F → E","A → B → D → E → C → F","A → C → B → F → D → E","A → C → F → E → D → B"],"ans":[0],"sol":["Hàng đợi [A]. Lấy A, in A, đưa B rồi C vào hàng đợi","Lấy B, in B; B có D nên đưa D vào hàng đợi","Lấy C, in C; C có D (đã đánh dấu) và F nên đưa F vào","Lấy D in D, đưa E; lấy F in F, E đã đánh dấu; lấy E in E","Kết quả: A → B → C → D → F → E"],"kq":"A → B → C → D → F → E","note":"BFS duyệt theo mức: A mức 0; B, C mức 1; D, F mức 2; E mức 3. A → B → D → E → C → F là DFS."},{"id":"ex-bfs-05","topic":"BFS-DFS","level":4,"q":"Cho đồ thị VÔ HƯỚNG sau. Duyệt DFS từ đỉnh C (không phải từ A). Khi có nhiều lựa chọn, duyệt theo thứ tự bảng chữ cái. Hãy cho biết thứ tự duyệt các đỉnh.","given":["Cạnh: A — B","Cạnh: A — C","Cạnh: B — D","Cạnh: B — E","Cạnh: C — F","Cạnh: D — G","Cạnh: E — G","Nguồn: C · nhiều lựa chọn thì theo bảng chữ cái"],"opts":["C → A → F → B → D → E → G","C → F → A → B → E → G → D","C → A → B → D → G → E → F","C → A → B → D → E → G → F"],"ans":[2],"sol":["Thăm C. Đỉnh kề của C là A và F; theo bảng chữ cái chọn A","Từ A, kề là B và C (C đã thăm) nên thăm B","Từ B, kề là A, D, E; A đã thăm nên thăm D","Từ D, kề là B, G; B đã thăm nên thăm G","Từ G, kề là D, E; D đã thăm nên thăm E; E kề B, G đều đã thăm nên quay lui","Quay về C, còn F nên thăm F. Kết quả: C → A → B → D → G → E → F"],"kq":"C → A → B → D → G → E → F","note":"C → A → F → B → D → E → G là BFS từ C. C → F → A → ... là duyệt theo thứ tự bảng chữ cái NGƯỢC. C → A → B → D → E → G → F bỏ qua việc G phải đi tiếp xuống E."},{"id":"ex-mp-01","topic":"Micro-partition","level":1,"q":"Một bảng trong Snowflake có 96 micro-partition, mỗi micro-partition chứa trung bình 500 MB dữ liệu nén. Tổng dung lượng nén của bảng là bao nhiêu GB? (1 GB = 1024 MB)","given":["Số micro-partition = 96","Dung lượng trung bình mỗi micro-partition = 500 MB dữ liệu nén","1 GB = 1024 MB"],"opts":["93,75","48","23,438","46,875"],"ans":[3],"sol":["Tổng dung lượng nén = 96 × 500 = 48000 MB","Đổi sang GB: 48000 ÷ 1024 = 46,875 GB","Nếu lấy 1 GB = 1000 MB sẽ ra 48 GB, đó là bẫy đơn vị","Kết quả: 46,875 GB"],"kq":"46,875 GB","note":"Micro-partition tính theo MB nén nên phải đổi bằng 1024. Quên đổi đơn vị là lỗi mất điểm phổ biến nhất của dạng bài này."},{"id":"ex-mp-02","topic":"Micro-partition","level":1,"q":"Một bảng có 12 GB dữ liệu nén. Giả sử mỗi micro-partition chứa tối đa 500 MB nén, hỏi cần ít nhất bao nhiêu micro-partition để lưu hết bảng? (1 GB = 1024 MB)","given":["Dung lượng nén của bảng = 12 GB","Kích thước tối đa mỗi micro-partition = 500 MB","1 GB = 1024 MB"],"opts":["24","25","12288","12"],"ans":[1],"sol":["Đổi sang MB: 12 × 1024 = 12288 MB","Số micro-partition = 12288 ÷ 500 = 24,576","Vì mỗi phân vùng không được vượt 500 MB nên phải làm tròn lên: 25 phân vùng","Kết quả: 25 micro-partition"],"kq":"25 micro-partition","note":"12288 là số MB chứ không phải số phân vùng; 24 là làm tròn xuống nên phân vùng cuối sẽ vượt 500 MB."},{"id":"ex-mp-06","topic":"Micro-partition","level":1,"q":"Một bảng có dung lượng nén 100 GB. Nếu mỗi micro-partition chứa tối đa 500 MB dữ liệu nén, số micro-partition tối thiểu cần có là bao nhiêu? (1 GB = 1024 MB)","given":["Dung lượng nén của bảng = 100 GB","Kích thước tối đa mỗi micro-partition = 500 MB","1 GB = 1024 MB"],"opts":["204","205","200","102400"],"ans":[1],"sol":["Đổi sang MB: 100 × 1024 = 102400 MB","Số phân vùng = 102400 ÷ 500 = 204,8","Phải làm tròn lên: 205 phân vùng","Kết quả: 205 micro-partition"],"kq":"205 micro-partition","note":"204 là làm tròn xuống (phân vùng cuối sẽ vượt 500 MB); 200 là khi dùng 1 GB = 1000 MB; 102400 là số MB, không phải số phân vùng."},{"id":"ex-mp-09","topic":"Micro-partition","level":1,"q":"Một bảng được chia thành 4096 micro-partition. Nhờ metadata Min/Max, truy vấn xác định chỉ 128 micro-partition chứa dữ liệu thoả điều kiện lọc. Bao nhiêu phần trăm số micro-partition được bỏ qua không đọc?","given":["Tổng số micro-partition = 4096","Số micro-partition khớp bộ lọc = 128","Data Pruning dựa trên metadata Min/Max của mỗi cột trong từng phân vùng"],"opts":["32 %","3,125 %","96,875 %","0,969 %"],"ans":[2],"sol":["Số phân vùng bị bỏ qua = 4096 − 128 = 3968","Tỉ lệ bỏ qua = 3968 ÷ 4096 = 0,96875","Đổi ra phần trăm: 0,96875 × 100 = 96,875 %","Kết quả: 96,875 %"],"kq":"96,875 %","note":"3,125 % là tỉ lệ phải đọc; 32 là tỉ số 4096/128 (chưa nhân 100 và chưa lấy phần bù); 0,969 % là quên nhân 100."},{"id":"ex-mp-03","topic":"Micro-partition","level":2,"q":"Một bảng có 3000 micro-partition, mỗi micro-partition chứa trung bình 250 MB dữ liệu nén. Tổng dung lượng nén của bảng là bao nhiêu GB? (1 GB = 1024 MB)","given":["Số micro-partition = 3000","Dung lượng trung bình mỗi micro-partition = 250 MB nén","1 GB = 1024 MB"],"opts":["750,000","732,422","1464,844","366,211"],"ans":[1],"sol":["Tổng dung lượng nén = 3000 × 250 = 750000 MB","Đổi sang GB: 750000 ÷ 1024 = 732,421875 GB","Làm tròn 3 chữ số thập phân được 732,422 GB","Kết quả: 732,422 GB"],"kq":"732,422 GB","note":"750,000 là đáp án khi dùng 1 GB = 1000 MB; 366,211 là khi chia đôi số MB một cách vô cớ."},{"id":"ex-mp-04","topic":"Micro-partition","level":2,"q":"Một bảng được chia thành 2048 micro-partition. Truy vấn có điều kiện lọc trên cột NgayDat; dựa vào metadata Min/Max của từng phân vùng, hệ thống xác định chỉ 128 micro-partition chứa dữ liệu thoả điều kiện. Nhờ Data Pruning, bao nhiêu phần trăm số micro-partition được bỏ qua không đọc?","given":["Tổng số micro-partition = 2048","Số micro-partition chứa dữ liệu thoả điều kiện = 128","Data Pruning dựa trên metadata Min/Max của mỗi cột trong từng phân vùng"],"opts":["93,75 %","6,25 %","1600 %","0,0625 %"],"ans":[0],"sol":["Số phân vùng bị bỏ qua = 2048 − 128 = 1920","Tỉ lệ bỏ qua = 1920 ÷ 2048 = 0,9375","Đổi ra phần trăm: 0,9375 × 100 = 93,75 %","Kết quả: 93,75 %"],"kq":"93,75 %","note":"6,25 % là tỉ lệ phải đọc (128/2048), tức phần bù; 1600 % là khi lấy 2048/128 rồi nhân 100 (đảo tử số và mẫu số)."},{"id":"ex-mp-07","topic":"Micro-partition","level":2,"q":"Một bảng có 2000 micro-partition, mỗi micro-partition chứa trung bình 400 MB dữ liệu nén. Tổng dung lượng nén của bảng là bao nhiêu GB? (1 GB = 1024 MB)","given":["Số micro-partition = 2000","Dung lượng trung bình mỗi micro-partition = 400 MB nén","1 GB = 1024 MB"],"opts":["390,625","800,000","1562,500","781,250"],"ans":[3],"sol":["Tổng dung lượng nén = 2000 × 400 = 800000 MB","Đổi sang GB: 800000 ÷ 1024 = 781,25 GB","Kết quả: 781,250 GB"],"kq":"781,250 GB","note":"800,000 là khi dùng 1 GB = 1000 MB; 1562,500 là khi nhân đôi số MB; 390,625 là khi chia đôi."},{"id":"ex-mp-08","topic":"Micro-partition","level":2,"q":"Một bảng nhỏ có dung lượng nén 24 GB. Với kích thước mỗi micro-partition là 250 MB dữ liệu nén, số micro-partition tối thiểu cần có là bao nhiêu? (1 GB = 1024 MB)","given":["Dung lượng nén của bảng = 24 GB","Kích thước mỗi micro-partition = 250 MB","1 GB = 1024 MB"],"opts":["96","98","99","24"],"ans":[2],"sol":["Đổi sang MB: 24 × 1024 = 24576 MB","Số phân vùng = 24576 ÷ 250 = 98,304","Làm tròn lên: 99 phân vùng","Kết quả: 99 micro-partition"],"kq":"99 micro-partition","note":"98 là làm tròn xuống; 96 là khi dùng 1 GB = 1000 MB; 24 là khi nhầm số GB thành số phân vùng."},{"id":"ex-mp-05","topic":"Micro-partition","level":3,"q":"Một bảng có dung lượng nén 3,5 TB. Với kích thước mỗi micro-partition là 500 MB dữ liệu nén, số micro-partition tối thiểu cần có là bao nhiêu? (1 TB = 1024 GB, 1 GB = 1024 MB)","given":["Dung lượng nén của bảng = 3,5 TB","Kích thước mỗi micro-partition = 500 MB nén","1 TB = 1024 GB, 1 GB = 1024 MB"],"opts":["7341","7340","7168","3584"],"ans":[0],"sol":["Đổi 3,5 TB sang MB: 3,5 × 1024 × 1024 = 3670016 MB","Số phân vùng = 3670016 ÷ 500 = 7340,032","Làm tròn lên vì còn dư: 7341 phân vùng","Kết quả: 7341 micro-partition"],"kq":"7341 micro-partition","note":"7340 là làm tròn xuống; 7168 ứng với kích thước 512 MB; 3584 chính là số GB của 3,5 TB (quên đổi ra MB)."},{"id":"ex-mp-10","topic":"Micro-partition","level":3,"q":"Một bảng gồm 7500 micro-partition, mỗi micro-partition chứa trung bình 300 MB dữ liệu nén. Truy vấn có bộ lọc mà metadata Min/Max cho thấy chỉ 16 % số micro-partition chứa dữ liệu cần đọc. Dung lượng dữ liệu thực tế phải đọc là bao nhiêu GB? (1 GB = 1024 MB)","given":["Tổng số micro-partition = 7500","Dung lượng trung bình mỗi micro-partition = 300 MB nén","Tỉ lệ micro-partition khớp bộ lọc = 16 %","1 GB = 1024 MB"],"opts":["351,563","360","2197,266","703,125"],"ans":[0],"sol":["Số phân vùng phải đọc = 7500 × 0,16 = 1200 phân vùng","Dung lượng đọc = 1200 × 300 = 360000 MB","Đổi sang GB: 360000 ÷ 1024 = 351,5625 GB","Kết quả: 351,563 GB"],"kq":"351,563 GB","note":"360 là khi dùng 1 GB = 1000 MB; 2197,266 là khi quên áp dụng Data Pruning (đọc cả 7500 phân vùng); 703,125 là khi tính với 32 % thay vì 16 %."},{"id":"ex-mp-11","topic":"Micro-partition","level":3,"q":"Bảng có 4096 micro-partition, mỗi micro-partition 400 MB dữ liệu nén. Tốc độ quét là 512 MB/giây. Nếu không pruning phải đọc toàn bộ bảng; nhờ metadata Min/Max truy vấn chỉ đọc 512 micro-partition. Thời gian tiết kiệm được là bao nhiêu giây?","given":["Tổng số micro-partition = 4096, mỗi micro-partition 400 MB nén","Số micro-partition phải đọc sau pruning = 512","Tốc độ quét = 512 MB/giây"],"opts":["2800","400","3200","2400"],"ans":[0],"sol":["Dữ liệu phải đọc khi không pruning = 4096 × 400 = 1638400 MB","Thời gian không pruning = 1638400 ÷ 512 = 3200 giây","Dữ liệu phải đọc sau pruning = 512 × 400 = 204800 MB","Thời gian sau pruning = 204800 ÷ 512 = 400 giây","Thời gian tiết kiệm = 3200 − 400 = 2800 giây","Kết quả: 2800 giây"],"kq":"2800 giây","note":"400 là thời gian sau pruning; 3200 là thời gian khi không pruning; 2400 là khi lấy 3200 − 800 (nhầm số phân vùng bị bỏ qua là 2 lần số phải đọc)."},{"id":"ex-cost-01","topic":"Chi phí Cloud","level":1,"q":"Một Virtual Warehouse size Medium chạy liên tục 3 giờ. Với đơn giá 2 USD/credit, chi phí compute của lần chạy này là bao nhiêu USD?","given":["Warehouse size = Medium","Thời gian chạy = 3 giờ","Đơn giá = 2 USD/credit","Quy đổi credit/giờ: X-Small 1 · Small 2 · Medium 4 · Large 8 · X-Large 16 · 2X-Large 32 · 3X-Large 64 · 4X-Large 128"],"opts":["48","12","24","6"],"ans":[2],"sol":["Medium tiêu thụ 4 credit/giờ","Số credit = 4 × 3 = 12 credit","Chi phí = 12 × 2 = 24 USD","Kết quả: 24 USD"],"kq":"24 USD","note":"12 là số credit (quên nhân đơn giá); 48 là khi nhầm Medium thành Large (8 credit/giờ); 6 là khi chia 12 cho 2 thay vì nhân."},{"id":"ex-cost-06","topic":"Chi phí Cloud","level":1,"q":"Một warehouse size 2X-Large chạy một job mất 30 phút. Đơn giá 3 USD/credit. Chi phí compute của job là bao nhiêu USD?","given":["Warehouse size = 2X-Large","Thời gian chạy = 30 phút = 0,5 giờ","Đơn giá = 3 USD/credit","Quy đổi credit/giờ: X-Small 1 · Small 2 · Medium 4 · Large 8 · X-Large 16 · 2X-Large 32 · 3X-Large 64 · 4X-Large 128"],"opts":["16","96","24","48"],"ans":[3],"sol":["2X-Large tiêu thụ 32 credit/giờ","Số credit = 32 × 0,5 = 16 credit","Chi phí = 16 × 3 = 48 USD","Kết quả: 48 USD"],"kq":"48 USD","note":"96 là khi tính tròn 1 giờ; 24 là khi nhầm sang X-Large (16 credit/giờ); 16 là số credit (quên nhân đơn giá)."},{"id":"ex-cost-02","topic":"Chi phí Cloud","level":2,"q":"Một warehouse size X-Large được bật để chạy một job mất 45 phút. Đơn giá 2,5 USD/credit. Chi phí compute của job là bao nhiêu USD?","given":["Warehouse size = X-Large","Thời gian chạy = 45 phút = 0,75 giờ","Đơn giá = 2,5 USD/credit","Quy đổi credit/giờ: X-Small 1 · Small 2 · Medium 4 · Large 8 · X-Large 16 · 2X-Large 32 · 3X-Large 64 · 4X-Large 128"],"opts":["15","40","30","60"],"ans":[2],"sol":["X-Large tiêu thụ 16 credit/giờ","Đổi 45 phút = 0,75 giờ; số credit = 16 × 0,75 = 12 credit","Chi phí = 12 × 2,5 = 30 USD","Kết quả: 30 USD"],"kq":"30 USD","note":"40 là khi tính tròn thành 1 giờ; 15 là khi nhầm sang Large (8 credit/giờ); 60 là khi nhầm sang 2X-Large (32 credit/giờ)."},{"id":"ex-cost-03","topic":"Chi phí Cloud","level":2,"q":"Warehouse size X-Small (1 credit/giờ) bật auto-suspend: cụm tự tắt ngay sau mỗi phiên truy vấn. Mỗi ngày có 180 phiên, mỗi phiên cụm bật đúng 2 phút. Đơn giá 2 USD/credit. Chi phí compute cho 30 ngày là bao nhiêu USD?","given":["Warehouse size = X-Small","180 phiên mỗi ngày, mỗi phiên cụm bật 2 phút","Đơn giá = 2 USD/credit","Tính cho 30 ngày","Quy đổi credit/giờ: X-Small 1 · Small 2 · Medium 4 · Large 8 · X-Large 16 · 2X-Large 32 · 3X-Large 64 · 4X-Large 128"],"opts":["360","12","720","180"],"ans":[0],"sol":["Thời gian bật mỗi ngày = 180 × 2 = 360 phút = 6 giờ","Số credit mỗi ngày = 6 × 1 = 6 credit","Chi phí mỗi ngày = 6 × 2 = 12 USD","Chi phí 30 ngày = 12 × 30 = 360 USD","Kết quả: 360 USD"],"kq":"360 USD","note":"12 là chi phí 1 ngày (quên nhân 30); 720 là khi nhầm X-Small thành Small; 180 là số credit của 30 ngày (quên nhân đơn giá)."},{"id":"ex-cost-07","topic":"Chi phí Cloud","level":2,"q":"Một warehouse size 4X-Large chạy 15 phút để nạp dữ liệu. Đơn giá 2,5 USD/credit. Chi phí compute của lần nạp này là bao nhiêu USD?","given":["Warehouse size = 4X-Large","Thời gian chạy = 15 phút = 0,25 giờ","Đơn giá = 2,5 USD/credit","Quy đổi credit/giờ: X-Small 1 · Small 2 · Medium 4 · Large 8 · X-Large 16 · 2X-Large 32 · 3X-Large 64 · 4X-Large 128"],"opts":["320","80","20","10"],"ans":[1],"sol":["4X-Large tiêu thụ 128 credit/giờ","Số credit = 128 × 0,25 = 32 credit","Chi phí = 32 × 2,5 = 80 USD","Kết quả: 80 USD"],"kq":"80 USD","note":"320 là khi tính tròn 1 giờ; 20 là khi nhầm sang 2X-Large (32 credit/giờ); 10 là khi nhầm sang X-Large (16 credit/giờ)."},{"id":"ex-cost-08","topic":"Chi phí Cloud","level":2,"q":"Một kho dữ liệu lưu trữ 250 TB dữ liệu. Đơn giá lưu trữ là 23 USD mỗi TB-tháng. Chi phí lưu trữ cho một tháng là bao nhiêu USD?","given":["Dung lượng lưu trữ = 250 TB","Đơn giá lưu trữ = 23 USD/TB-tháng","Chi phí lưu trữ tính theo TB-tháng sử dụng"],"opts":["575","5750","10,87","11500"],"ans":[1],"sol":["Chi phí = dung lượng × đơn giá","= 250 × 23 = 5750 USD","Kết quả: 5750 USD"],"kq":"5750 USD","note":"575 là khi mất một chữ số 0 của dung lượng; 10,87 là khi chia thay vì nhân (250/23); 11500 là khi nhân đôi dung lượng."},{"id":"ex-cost-04","topic":"Chi phí Cloud","level":3,"q":"Warehouse size Large, đơn giá 3 USD/credit. Mỗi ngày có 40 truy vấn, mỗi truy vấn chạy 5 phút. Nếu bật auto-suspend 60 giây thì cụm chỉ bật đúng thời gian chạy; nếu tắt auto-suspend thì cụm bật suốt 12 giờ mỗi ngày. Trong 30 ngày, bật auto-suspend tiết kiệm bao nhiêu USD?","given":["Warehouse size = Large","40 truy vấn mỗi ngày, mỗi truy vấn 5 phút","Không auto-suspend: cụm bật 12 giờ mỗi ngày","Đơn giá = 3 USD/credit","Quy đổi credit/giờ: X-Small 1 · Small 2 · Medium 4 · Large 8 · X-Large 16 · 2X-Large 32 · 3X-Large 64 · 4X-Large 128"],"opts":["208","6240","3120","12480"],"ans":[1],"sol":["Có auto-suspend: 40 × 5 = 200 phút = 3,3333 giờ mỗi ngày","Credit mỗi ngày = 3,3333 × 8 = 26,6667 credit, tức 26,6667 × 3 = 80 USD/ngày","Chi phí 30 ngày = 80 × 30 = 2400 USD","Không auto-suspend: 12 × 8 × 3 = 288 USD/ngày, tức 288 × 30 = 8640 USD cho 30 ngày","Tiết kiệm = 8640 − 2400 = 6240 USD","Kết quả: 6240 USD"],"kq":"6240 USD","note":"208 là chênh lệch của 1 ngày (288 − 80) khi quên nhân 30; 3120 là khi nhầm Medium (4 credit/giờ); 12480 là khi nhầm X-Large (16 credit/giờ)."},{"id":"ex-cost-05","topic":"Chi phí Cloud","level":3,"q":"Warehouse size Medium, auto-suspend đặt 5 phút, đơn giá 2,5 USD/credit. Mỗi ngày có 24 phiên, mỗi phiên chạy 6 phút; do auto-suspend 5 phút nên cụm thực tế bật 11 phút mỗi phiên rồi mới tắt. Chi phí compute cho 30 ngày là bao nhiêu USD?","given":["Warehouse size = Medium","24 phiên mỗi ngày, mỗi phiên cụm bật 6 phút chạy + 5 phút chờ auto-suspend = 11 phút","Đơn giá = 2,5 USD/credit","Tính cho 30 ngày","Quy đổi credit/giờ: X-Small 1 · Small 2 · Medium 4 · Large 8 · X-Large 16 · 2X-Large 32 · 3X-Large 64 · 4X-Large 128"],"opts":["44","720","2640","1320"],"ans":[3],"sol":["Thời gian bật mỗi ngày = 24 × 11 = 264 phút = 4,4 giờ","Credit mỗi ngày = 4,4 × 4 = 17,6 credit","Chi phí mỗi ngày = 17,6 × 2,5 = 44 USD","Chi phí 30 ngày = 44 × 30 = 1320 USD","Kết quả: 1320 USD"],"kq":"1320 USD","note":"720 là khi bỏ qua 5 phút chờ auto-suspend; 2640 là khi nhầm sang Large; 44 là chi phí 1 ngày."},{"id":"ex-cost-09","topic":"Chi phí Cloud","level":3,"q":"Warehouse size Medium, đơn giá 2 USD/credit. Mỗi ngày có 60 phiên, mỗi phiên chạy 4 phút. Nếu bật auto-suspend thì cụm chỉ bật đúng 4 giờ mỗi ngày; nếu tắt auto-suspend thì cụm bật 10 giờ mỗi ngày. Trong 30 ngày, bật auto-suspend tiết kiệm bao nhiêu USD?","given":["Warehouse size = Medium","60 phiên mỗi ngày, mỗi phiên 4 phút, tổng 4 giờ mỗi ngày","Không auto-suspend: cụm bật 10 giờ mỗi ngày","Đơn giá = 2 USD/credit","Tính cho 30 ngày","Quy đổi credit/giờ: X-Small 1 · Small 2 · Medium 4 · Large 8 · X-Large 16 · 2X-Large 32 · 3X-Large 64 · 4X-Large 128"],"opts":["2880","48","1440","720"],"ans":[2],"sol":["Có auto-suspend: 4 giờ/ngày × 4 credit/giờ × 2 USD = 32 USD/ngày","30 ngày: 32 × 30 = 960 USD","Không auto-suspend: 10 × 4 × 2 = 80 USD/ngày, tức 80 × 30 = 2400 USD","Tiết kiệm = 2400 − 960 = 1440 USD","Kết quả: 1440 USD"],"kq":"1440 USD","note":"48 là chênh lệch của 1 ngày (80 − 32) khi quên nhân 30; 2880 là khi nhầm sang Large (8 credit/giờ); 720 là khi nhầm sang Small (2 credit/giờ)."},{"id":"ex-olap-01","topic":"OLAP-cube","level":1,"q":"Một data cube có 4 chiều: ThoiGian 12 giá trị, SanPham 8 giá trị, Vung 5 giá trị, CuaHang 100 giá trị. Tổng số ô (cell) của cube là bao nhiêu?","given":["ThoiGian = 12 giá trị","SanPham = 8 giá trị","Vung = 5 giá trị","CuaHang = 100 giá trị"],"opts":["125","48000","4800","192000"],"ans":[1],"sol":["Số ô = tích số giá trị của các chiều","12 × 8 = 96","96 × 5 = 480","480 × 100 = 48000 ô","Kết quả: 48000 ô"],"kq":"48000 ô","note":"125 là tổng số giá trị các chiều (cộng thay vì nhân); 4800 là khi bỏ mất một chữ số 0 của chiều cửa hàng."},{"id":"ex-olap-05","topic":"OLAP-cube","level":1,"q":"Một data cube có 3 chiều với số giá trị lần lượt là 10, 6 và 4. Tổng số ô (cell) của cube là bao nhiêu?","given":["Chiều 1 = 10 giá trị","Chiều 2 = 6 giá trị","Chiều 3 = 4 giá trị"],"opts":["60","20","480","240"],"ans":[3],"sol":["Số ô = tích số giá trị của các chiều","10 × 6 = 60","60 × 4 = 240 ô","Kết quả: 240 ô"],"kq":"240 ô","note":"20 là tổng số giá trị các chiều (cộng thay vì nhân); 480 là khi nhân đôi; 60 là khi quên nhân chiều thứ ba."},{"id":"ex-olap-02","topic":"OLAP-cube","level":2,"q":"Một cube lý thuyết có 6 × 4 × 3 × 5 = 360 ô. Khảo sát thực tế thấy chỉ 270 ô có dữ liệu. Tỉ lệ ô rỗng là bao nhiêu phần trăm?","given":["Tổng số ô lý thuyết = 360","Số ô có dữ liệu = 270","Số ô rỗng = tổng số ô − số ô có dữ liệu"],"opts":["12,5 %","75 %","33,333 %","25 %"],"ans":[3],"sol":["Số ô rỗng = 360 − 270 = 90","Tỉ lệ = 90 ÷ 360 = 0,25","Đổi ra phần trăm: 0,25 × 100 = 25 %","Kết quả: 25 %"],"kq":"25 %","note":"75 % là tỉ lệ ô CÓ dữ liệu; 33,333 % là khi lấy 90 chia cho 270 (chia nhầm mẫu số)."},{"id":"ex-olap-03","topic":"OLAP-cube","level":2,"q":"Cube có chiều thời gian phân cấp: 365 ngày → 12 tháng → 1 năm; kèm hai chiều SanPham (8 giá trị) và Vung (5 giá trị). Nếu tính cả mọi mức tổng hợp của chiều thời gian, tổng số ô của cube là bao nhiêu?","given":["Chiều thời gian có 3 mức: 365 ngày, 12 tháng, 1 năm","SanPham = 8 giá trị","Vung = 5 giá trị"],"opts":["175200","14600","15120","3024"],"ans":[2],"sol":["Số mức của chiều thời gian = 365 + 12 + 1 = 378","Số ô = 378 × 8 × 5","378 × 8 = 3024","3024 × 5 = 15120 ô","Kết quả: 15120 ô"],"kq":"15120 ô","note":"14600 là 365 × 8 × 5 (bỏ các mức tổng hợp); 175200 là 365 × 12 × 8 × 5 (nhân các mức thay vì cộng); 3024 là khi quên nhân chiều Vung."},{"id":"ex-olap-06","topic":"OLAP-cube","level":2,"q":"Một cube có 3 chiều: 8 × 4 × 12 = 384 ô. Khảo sát thực tế thấy chỉ 96 ô có dữ liệu. Tỉ lệ ô rỗng là bao nhiêu phần trăm?","given":["Tổng số ô lý thuyết = 384","Số ô có dữ liệu = 96","Số ô rỗng = tổng số ô − số ô có dữ liệu"],"opts":["75 %","25 %","96 %","12,5 %"],"ans":[0],"sol":["Số ô rỗng = 384 − 96 = 288","Tỉ lệ rỗng = 288 ÷ 384 = 0,75","Đổi ra phần trăm: 0,75 × 100 = 75 %","Kết quả: 75 %"],"kq":"75 %","note":"25 % là tỉ lệ ô CÓ dữ liệu; 96 % là khi lấy số ô có dữ liệu chia 100; 12,5 % là khi lấy 96/384 rồi chia đôi."},{"id":"ex-olap-04","topic":"OLAP-cube","level":3,"q":"Một cube thưa có 48000 ô, trong đó 30000 ô rỗng và 18000 ô có dữ liệu. Mỗi ô rỗng tốn 40 byte, mỗi ô có dữ liệu tốn 120 byte. Dung lượng lưu trữ của cube là bao nhiêu MB? (1 MB = 1024 × 1024 = 1048576 byte)","given":["Số ô rỗng = 30000, mỗi ô rỗng = 40 byte","Số ô có dữ liệu = 18000, mỗi ô có dữ liệu = 120 byte","1 MB = 1048576 byte"],"opts":["3,204 MB","3,281 MB","2,060 MB","4,120 MB"],"ans":[0],"sol":["Dung lượng phần ô rỗng = 30000 × 40 = 1200000 byte","Dung lượng phần ô có dữ liệu = 18000 × 120 = 2160000 byte","Tổng = 1200000 + 2160000 = 3360000 byte","Đổi sang MB: 3360000 ÷ 1048576 = 3,2044 MB","Kết quả: 3,204 MB"],"kq":"3,204 MB","note":"3,281 MB là khi lấy 1 MB = 1024000 byte; 2,060 MB là khi bỏ qua toàn bộ ô rỗng; 4,120 MB là khi hoán đổi số ô rỗng và số ô có dữ liệu."},{"id":"ex-olap-07","topic":"OLAP-cube","level":3,"q":"Một cube chi tiết có 192000 ô. Sau khi roll-up bỏ hẳn chiều CuaHang và chiều Ngay (mỗi chiều còn đúng 1 mức tổng), cube kết quả còn 384 ô. Số ô giảm bao nhiêu phần trăm?","given":["Số ô trước roll-up = 192000","Số ô sau roll-up = 384","Roll-up bỏ hẳn 2 chiều, mỗi chiều chỉ còn 1 mức tổng"],"opts":["0,2 %","99,8 %","500 %","99,2 %"],"ans":[1],"sol":["Số ô giảm = 192000 − 384 = 191616","Tỉ lệ giảm = 191616 ÷ 192000 = 0,998","Đổi ra phần trăm: 0,998 × 100 = 99,8 %","Kết quả: 99,8 %"],"kq":"99,8 %","note":"0,2 % là tỉ lệ còn lại (384/192000); 500 là tỉ số 192000/384 (chưa nhân 100 và chưa lấy phần bù); 99,2 % là khi lấy 100 − 0,8."},{"id":"ex-bqml-01","topic":"BigQuery-ML","level":1,"q":"Mô hình phân loại churn chạy trên 1000 khách hàng cho kết quả TP = 40, FP = 60, FN = 10, TN = 890. Precision của mô hình là bao nhiêu?","given":["TP = 40","FP = 60","FN = 10","TN = 890","Tổng số mẫu = 1000","Precision = TP ÷ (TP + FP)","Recall = TP ÷ (TP + FN)","Accuracy = (TP + TN) ÷ tổng số mẫu"],"opts":["2,500","0,800","0,930","0,400"],"ans":[3],"sol":["TP + FP = 40 + 60 = 100","Precision = 40 ÷ 100 = 0,400","Kiểm tra chéo: Recall = 40 ÷ (40 + 10) = 0,800; Accuracy = (40 + 890) ÷ 1000 = 0,930","Kết quả: 0,400"],"kq":"0,400","note":"0,800 là Recall, 0,930 là Accuracy; 2,500 là khi đảo tử số và mẫu số (100/40)."},{"id":"ex-bqml-05","topic":"BigQuery-ML","level":1,"q":"Mô hình phân loại chạy trên 1000 khách hàng cho TP = 40, FP = 40, FN = 10, TN = 910. Precision của mô hình là bao nhiêu?","given":["TP = 40","FP = 40","FN = 10","TN = 910","Tổng số mẫu = 1000","Precision = TP ÷ (TP + FP)","Recall = TP ÷ (TP + FN)","Accuracy = (TP + TN) ÷ tổng số mẫu"],"opts":["0,800","0,500","0,950","2,000"],"ans":[1],"sol":["TP + FP = 40 + 40 = 80","Precision = 40 ÷ 80 = 0,500","Kiểm tra chéo: Recall = 40 ÷ 50 = 0,800; Accuracy = (40 + 910) ÷ 1000 = 0,950","Kết quả: 0,500"],"kq":"0,500","note":"0,800 là Recall, 0,950 là Accuracy; 2,000 là khi đảo tử số và mẫu số của Precision."},{"id":"ex-bqml-02","topic":"BigQuery-ML","level":2,"q":"Mô hình dự báo rời bỏ khách hàng có TP = 120, FP = 150, FN = 35, TN = 795. F1-Score của mô hình là bao nhiêu?","given":["TP = 120","FP = 150","FN = 35","TN = 795","Precision = TP ÷ (TP + FP)","Recall = TP ÷ (TP + FN)","F1 = 2 × Precision × Recall ÷ (Precision + Recall)"],"opts":["0,565","0,609","0,344","1,219"],"ans":[0],"sol":["Precision = 120 ÷ (120 + 150) = 120 ÷ 270 = 0,444","Recall = 120 ÷ (120 + 35) = 120 ÷ 155 = 0,774","Tử số 2 × 0,444 × 0,774 = 0,688; mẫu số 0,444 + 0,774 = 1,219","F1 = 0,688 ÷ 1,219 = 0,5647","Kết quả: 0,565"],"kq":"0,565","note":"0,609 là trung bình cộng (Precision + Recall)/2, không phải F1; 0,344 là tích Precision × Recall; 1,219 là tổng Precision + Recall (quên chia)."},{"id":"ex-bqml-03","topic":"BigQuery-ML","level":2,"q":"Với confusion matrix TP = 180, FP = 45, FN = 20, TN = 755 trên 1000 khách hàng, Recall của mô hình là bao nhiêu?","given":["TP = 180","FP = 45","FN = 20","TN = 755","Tổng số mẫu = 1000","Recall = TP ÷ (TP + FN)","Precision = TP ÷ (TP + FP)"],"opts":["0,935","0,800","0,900","0,065"],"ans":[2],"sol":["Số mẫu thực sự churn = TP + FN = 180 + 20 = 200","Recall = 180 ÷ 200 = 0,900","Kiểm tra chéo: Precision = 180 ÷ 225 = 0,800; Accuracy = (180 + 755) ÷ 1000 = 0,935","Kết quả: 0,900"],"kq":"0,900","note":"Mẫu số của Recall là TP + FN (tổng số mẫu thực sự churn), không phải TP + FP. 0,065 là tỉ lệ lỗi (1 − Accuracy)."},{"id":"ex-bqml-06","topic":"BigQuery-ML","level":2,"q":"Mô hình dự báo rời bỏ khách hàng có TP = 150, FP = 50, FN = 90, TN = 710. F1-Score của mô hình là bao nhiêu?","given":["TP = 150","FP = 50","FN = 90","TN = 710","Precision = TP ÷ (TP + FP)","Recall = TP ÷ (TP + FN)","F1 = 2 × Precision × Recall ÷ (Precision + Recall)"],"opts":["0,682","0,688","0,469","1,375"],"ans":[0],"sol":["Precision = 150 ÷ 200 = 0,750","Recall = 150 ÷ 240 = 0,625","Tử số 2 × 0,750 × 0,625 = 0,9375; mẫu số 0,750 + 0,625 = 1,375","F1 = 0,9375 ÷ 1,375 = 0,6818","Kết quả: 0,682"],"kq":"0,682","note":"0,688 là trung bình cộng (0,750 + 0,625)/2; 0,469 là tích Precision × Recall; 1,375 là tổng Precision + Recall (quên chia)."},{"id":"ex-bqml-04","topic":"BigQuery-ML","level":3,"q":"Một mô hình phát hiện giao dịch gian lận có TP = 90, FP = 30, FN = 210, TN = 670. F1-Score của mô hình là bao nhiêu?","given":["TP = 90","FP = 30","FN = 210","TN = 670","Tổng số mẫu = 1000","Precision = TP ÷ (TP + FP)","Recall = TP ÷ (TP + FN)","F1 = 2 × Precision × Recall ÷ (Precision + Recall)"],"opts":["0,225","0,525","0,429","0,760"],"ans":[2],"sol":["Precision = 90 ÷ (90 + 30) = 90 ÷ 120 = 0,750","Recall = 90 ÷ (90 + 210) = 90 ÷ 300 = 0,300","F1 = 2 × 0,750 × 0,300 ÷ (0,750 + 0,300) = 0,450 ÷ 1,050","F1 = 0,4286","Kết quả: 0,429"],"kq":"0,429","note":"0,525 là trung bình cộng; 0,225 là Precision × Recall; 0,760 là Accuracy. Accuracy cao mà F1 thấp là dấu hiệu mất cân bằng lớp điển hình."},{"id":"ex-bqml-07","topic":"BigQuery-ML","level":3,"q":"Một mô hình phát hiện gian lận có TP = 60, FP = 15, FN = 140, TN = 785. F1-Score của mô hình là bao nhiêu?","given":["TP = 60","FP = 15","FN = 140","TN = 785","Tổng số mẫu = 1000","Precision = TP ÷ (TP + FP)","Recall = TP ÷ (TP + FN)","F1 = 2 × Precision × Recall ÷ (Precision + Recall)"],"opts":["0,240","0,550","0,436","0,845"],"ans":[2],"sol":["Precision = 60 ÷ 75 = 0,800","Recall = 60 ÷ 200 = 0,300","F1 = 2 × 0,800 × 0,300 ÷ (0,800 + 0,300) = 0,480 ÷ 1,100","F1 = 0,4364","Kết quả: 0,436"],"kq":"0,436","note":"0,550 là trung bình cộng; 0,240 là Precision × Recall; 0,845 là Accuracy. Accuracy 0,845 nhưng F1 chỉ 0,436 là biểu hiện điển hình của mất cân bằng lớp."},{"id":"ex-tonghop-01","topic":"Tổng hợp","level":4,"q":"Bảng gồm 8192 micro-partition, mỗi micro-partition 450 MB dữ liệu nén. Một truy vấn có bộ lọc mà metadata Min/Max cho thấy chỉ khớp 2048 micro-partition. Tốc độ quét là 512 MB/giây tính trên dung lượng thực đọc, warehouse size X-Large, đơn giá 2,5 USD/credit. Chi phí compute cho truy vấn này là bao nhiêu USD?","given":["Tổng số micro-partition = 8192, mỗi micro-partition 450 MB nén","Số micro-partition khớp bộ lọc = 2048","Tốc độ quét = 512 MB/giây","Warehouse size = X-Large","Đơn giá = 2,5 USD/credit","Quy đổi credit/giờ: X-Small 1 · Small 2 · Medium 4 · Large 8 · X-Large 16 · 2X-Large 32 · 3X-Large 64 · 4X-Large 128"],"opts":["80","20","5","10"],"ans":[1],"sol":["Bước 1 (Data Pruning): dữ liệu thực đọc = 2048 × 450 = 921600 MB","Bước 2 (thời gian): 921600 ÷ 512 = 1800 giây = 0,5 giờ","Bước 3 (credit): 0,5 × 16 = 8 credit","Bước 4 (chi phí): 8 × 2,5 = 20 USD","Kết quả: 20 USD"],"kq":"20 USD","note":"80 USD là khi bỏ qua Data Pruning và quét cả 8192 phân vùng (7200 giây = 2 giờ); 10 USD là khi nhầm size Large; 5 USD là khi nhầm size Medium."},{"id":"ex-tonghop-02","topic":"Tổng hợp","level":4,"q":"Báo cáo tháng có thể chạy trên bảng fact chi tiết (quét 1440 ms mỗi truy vấn) hoặc trên bảng tổng hợp Gold đã roll-up theo tháng (quét 144 ms mỗi truy vấn). Mỗi ngày có 5000 truy vấn, chạy trong 30 ngày, warehouse size Large, đơn giá 2,5 USD/credit. Dùng bảng tổng hợp thay bảng chi tiết tiết kiệm bao nhiêu USD?","given":["Thời gian quét bảng fact chi tiết = 1440 ms mỗi truy vấn","Thời gian quét bảng roll-up = 144 ms mỗi truy vấn","5000 truy vấn mỗi ngày, trong 30 ngày","Warehouse size = Large","Đơn giá = 2,5 USD/credit","Quy đổi credit/giờ: X-Small 1 · Small 2 · Medium 4 · Large 8 · X-Large 16 · 2X-Large 32 · 3X-Large 64 · 4X-Large 128"],"opts":["2160","120","1200","1080"],"ans":[3],"sol":["Thời gian tiết kiệm mỗi truy vấn = 1440 − 144 = 1296 ms","Tổng thời gian tiết kiệm = 1296 × 5000 × 30 = 194400000 ms = 194400 giây","Đổi ra giờ: 194400 ÷ 3600 = 54 giờ","Số credit = 54 × 8 = 432 credit; chi phí = 432 × 2,5 = 1080 USD","Kết quả: 1080 USD"],"kq":"1080 USD","note":"1200 là chi phí vẫn quét bảng chi tiết (60 giờ); 120 là chi phí quét bảng roll-up (6 giờ); 2160 là khi nhầm sang X-Large (16 credit/giờ)."},{"id":"ex-tonghop-03","topic":"Tổng hợp","level":4,"q":"Thu nhập khách hàng có min = 20 triệu, max = 120 triệu. Sau khi chuẩn hoá Min-Max về [0, 1], dữ liệu được chia thành 4 khoảng đều nhau (equal-width). Khách hàng có thu nhập 68 triệu nằm ở khoảng thứ hai, hỏi biên dưới của khoảng đó bằng bao nhiêu?","given":["min = 20 triệu, max = 120 triệu","Giá trị cần xét = 68 triệu","Chuẩn hoá Min-Max: v' = (v − min) ÷ (max − min), đưa về [0, 1]","Chia [0, 1] thành 4 khoảng đều nhau (equal-width)"],"opts":["0,25","0,50","0,00","0,75"],"ans":[0],"sol":["Bước 1 (Min-Max): v' = (68 − 20) ÷ (120 − 20) = 48 ÷ 100 = 0,48","Bước 2 (Equal-width): độ rộng mỗi khoảng = 1 ÷ 4 = 0,25","Các khoảng là [0; 0,25), [0,25; 0,5), [0,5; 0,75), [0,75; 1]","0,48 nằm trong khoảng [0,25; 0,5) nên biên dưới là 0,25","Kết quả: 0,25"],"kq":"0,25","note":"0,50 là biên TRÊN của khoảng (nhầm biên); 0,00 là khoảng thứ nhất (bỏ bước chuẩn hoá); 0,75 là khi nhầm 0,48 thành khoảng thứ tư do đọc sai độ rộng."},{"id":"ex-tonghop-04","topic":"Tổng hợp","level":4,"q":"Cơ sở dữ liệu giao dịch có 10 giao dịch: 6 giao dịch chứa X, 5 giao dịch chứa Y, 4 giao dịch chứa cả X và Y. Luật kết hợp X → Y có Lift bằng bao nhiêu?","given":["Tổng số giao dịch = 10","Số giao dịch chứa X = 6","Số giao dịch chứa Y = 5","Số giao dịch chứa cả X và Y = 4","Support(X ∪ Y) = 4 ÷ 10","Lift = Support(X ∪ Y) ÷ (Support(X) × Support(Y))"],"opts":["0,667","0,100","1,333","0,750"],"ans":[2],"sol":["Bước 1 (Support): Support(X) = 6/10 = 0,6; Support(Y) = 5/10 = 0,5; Support(X ∪ Y) = 4/10 = 0,4","Bước 2 (Lift): mẫu số = 0,6 × 0,5 = 0,3","Lift = 0,4 ÷ 0,3 = 1,3333","Vì Lift > 1 nên X và Y có tương quan dương","Kết quả: 1,333"],"kq":"1,333","note":"0,100 là hiệu Leverage (0,4 − 0,3); 0,667 là Confidence = 4/6 (chia cho số giao dịch chứa tiền đề chứ không phải công thức Lift); 0,750 là khi lấy 0,3/0,4 (đảo ngược)."},{"id":"ex-tonghop-05","topic":"Tổng hợp","level":4,"q":"Bảng có 2048 micro-partition, mỗi micro-partition 500 MB dữ liệu nén. Một bộ lọc mà metadata Min/Max cho thấy chỉ khớp 128 micro-partition. Tốc độ quét 512 MB/giây tính trên dữ liệu thực đọc. Warehouse size X-Large, đơn giá 2 USD/credit. Tính chi phí compute tiết kiệm được khi áp dụng Data Pruning cho 900 truy vấn giống nhau.","given":["Tổng số micro-partition = 2048, mỗi micro-partition 500 MB nén","Số micro-partition khớp bộ lọc = 128","Tốc độ quét = 512 MB/giây","Warehouse size = X-Large","Đơn giá = 2 USD/credit","900 truy vấn giống nhau","Quy đổi credit/giờ: X-Small 1 · Small 2 · Medium 4 · Large 8 · X-Large 16 · 2X-Large 32 · 3X-Large 64 · 4X-Large 128"],"opts":["16,67","3750","7500","15000"],"ans":[3],"sol":["Bước 1 (Pruning): dữ liệu đọc khi không pruning = 2048 × 500 = 1024000 MB, thời gian = 1024000 ÷ 512 = 2000 giây","Dữ liệu đọc sau pruning = 128 × 500 = 64000 MB, thời gian = 64000 ÷ 512 = 125 giây","Thời gian tiết kiệm mỗi truy vấn = 2000 − 125 = 1875 giây = 0,520833 giờ","Bước 2 (Chi phí): 900 truy vấn tiết kiệm 1875 × 900 = 1687500 giây = 468,75 giờ","Chi phí = 468,75 × 16 × 2 = 15000 USD","Kết quả: 15000 USD"],"kq":"15000 USD","note":"16,67 là tiền tiết kiệm của MỘT truy vấn (quên nhân 900); 3750 là khi nhầm size Medium; 7500 là khi nhầm size Large."},{"id":"ex-tonghop-06","topic":"Tổng hợp","level":4,"q":"Một kho dữ liệu có 12 TB dữ liệu. Dùng Lifecycle Policy chuyển 70 % dung lượng sang Archive tier (4 USD/TB-tháng) và giữ 30 % ở Hot tier (23 USD/TB-tháng). Chi phí lưu trữ một tháng sau khi phân tầng là bao nhiêu USD?","given":["Tổng dung lượng = 12 TB","Tỉ lệ chuyển Archive = 70 %, đơn giá 4 USD/TB-tháng","Tỉ lệ giữ Hot = 30 %, đơn giá 23 USD/TB-tháng"],"opts":["207,60","276,00","48,00","116,40"],"ans":[3],"sol":["Bước 1 (phân tầng): dung lượng Archive = 12 × 0,7 = 8,4 TB; dung lượng Hot = 12 × 0,3 = 3,6 TB","Bước 2 (chi phí từng tầng): Archive = 8,4 × 4 = 33,6 USD; Hot = 3,6 × 23 = 82,8 USD","Tổng chi phí = 33,6 + 82,8 = 116,4 USD","Kết quả: 116,40 USD"],"kq":"116,40 USD","note":"276 là chi phí khi để toàn bộ 12 TB ở Hot tier; 48 là khi để toàn bộ ở Archive tier; 207,60 là khi hoán đổi đơn giá giữa hai tầng."}];
if (typeof module !== "undefined" && module.exports) { module.exports = EXERCISES; }
